    public static List<String> selectedLocationSidebarLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        CampaignLocation selected = selectedCampaignLocation(ctx);
        if (ctx == null || st == null) return List.of("No location selected.");
        if (selected == null) {
            if (hasSelectedCampaignContactTarget(ctx)) return selectedContactSidebarLines(ctx);
            if (!hasSelectedFreeTravelTarget(ctx)) return List.of("No location selected.");
            return freeTravelSelectionLines(ctx);
        }
        ArrayList<String> out = new ArrayList<>();
        out.add("Type: " + selected.type.name().replace('_', ' '));
        out.add("Alignment: " + selectedLocationAlignmentLabel(selected) + "  |  Intel " + contactIntelQualityLabel(selected.intelQuality));
        out.add("Threat: " + threatReadoutForSidebar(selected.threatLevel) + "  |  Fleet Order " + campaignFleetPostureReadout(ctx));
        if (requiresEarthPhaseUnlock(selected) && !earthPhaseUnlocked(st)) {
            out.add("Earth Gate: LOCKED  |  Stabilize " + earthPhaseMinStabilizedTheatersRequired()
                    + " theaters (" + stabilizedTheaterCount(st) + "/" + earthPhaseMinStabilizedTheatersRequired() + ")");
        }
        out.add("Docking: " + dockingStatusReadout(ctx, selected));
        String chain = campaignDiscoveryChainLine(selected);
        if (!chain.isBlank()) out.add("Chain: " + chain);
        out.add(selectedStrategicPurposeLine(ctx, selected));
        out.add(selectedStrategicRewardLine(ctx, selected));
        out.add(selectedStrategicIgnoreLine(ctx, selected));
        String scanDetail = selectedSiteScanDetailLine(ctx, selected);
        if (!scanDetail.isBlank()) out.add(scanDetail);
        String timeWindow = selectedStrategicTimeWindowLine(ctx, selected);
        if (!timeWindow.isBlank()) out.add(timeWindow);
        out.add(selectedStrategicOpportunityLine(ctx, selected));
        out.add(selectedStrategicRiskLine(ctx, selected));
        CampaignAction primaryAction = campaignPrimaryAction(ctx);
        if (primaryAction != null && !primaryAction.label.isBlank()) {
            out.add("Primary Recommendation: " + primaryAction.label);
        }
        String resolution = selectedSiteResolutionModeReadout(ctx);
        if (!resolution.isBlank()) out.add("Site Plan: " + resolution);
        String escalation = campaignEscalationLine(selected);
        if (!escalation.isBlank()) out.add("Contact State: " + escalation);
        String memory = campaignSiteMemoryLine(selected);
        if (!memory.isBlank()) out.add("Site Memory: " + memory);
        String contact = campaignRecurringContactLine(ctx, selected);
        if (!contact.isBlank()) out.add("Known Contact: " + contact);
        String routeState = campaignRouteStateLine(selected);
        if (!routeState.isBlank()) out.add("Travel Result: " + routeState);
        String scar = campaignScarLine(selected);
        if (!scar.isBlank()) out.add("Scar: " + scar);
        addCompactBattleContextToSelectedSidebar(out, campaignBattleContextLines(ctx));
        out.addAll(compactRouteAssessmentLines(ctx));
        out.add("Region Note: " + regionIdentitySummaryFor(ctx, selected.x, selected.y));
        trimSelectedLocationSidebarLines(out);
        return out;
    }

    private static void addCompactBattleContextToSelectedSidebar(ArrayList<String> out, List<String> context) {
        if (out == null || context == null || context.isEmpty()) return;
        int added = 0;
        for (String line : context) {
            if (line == null || line.isBlank()) continue;
            if (line.contains("no battle expected") || line.contains("DANGER LOW")) continue;
            out.add(line);
            if (++added >= 2) break;
        }
    }

    private static void trimSelectedLocationSidebarLines(ArrayList<String> out) {
        if (out == null) return;
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Available Actions: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Support: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Battle Reason: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Hub Safety: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Danger Trend: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Route: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Threat Exposure: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Route Warning: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Recovery Route: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Region Note: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Site Plan: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Scar: ")) {}
        while (out.size() > 15 && removeFirstSidebarLineStartingWith(out, "Known Contact: ")) {}
        while (out.size() > 15 && removeLastSidebarLineNotStartingWith(out,
                "Why It Matters: ", "Gain: ", "If Ignored: ", "Available Action: ", "Risk: ",
                "Primary Recommendation: ", "Contact State: ", "Site Memory: ", "Time Limit: ",
                "Travel Result: ")) {}
        while (out.size() > 15) out.remove(out.size() - 1);
    }

    private static boolean removeFirstSidebarLineStartingWith(ArrayList<String> out, String prefix) {
        if (out == null || prefix == null) return false;
        for (int i = 0; i < out.size(); i++) {
            String line = out.get(i);
            if (line != null && line.startsWith(prefix)) {
                out.remove(i);
                return true;
            }
        }
        return false;
    }

    private static boolean removeLastSidebarLineNotStartingWith(ArrayList<String> out, String... protectedPrefixes) {
        if (out == null || out.isEmpty()) return false;
        for (int i = out.size() - 1; i >= 0; i--) {
            String line = out.get(i);
            boolean protectedLine = false;
            if (line != null && protectedPrefixes != null) {
                for (String prefix : protectedPrefixes) {
                    if (prefix != null && line.startsWith(prefix)) {
                        protectedLine = true;
                        break;
                    }
                }
            }
            if (!protectedLine) {
                out.remove(i);
                return true;
            }
        }
        return false;
    }

    public static List<String> campaignBattleContextLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        CampaignLocation selected = selectedCampaignLocation(ctx);
        if (ctx == null || st == null || selected == null) return List.of();
        ArrayList<String> out = new ArrayList<>();
        GalaxySearchGroup installationThreat = trackedHostileThreatForInstallation(ctx, st, selected);
        CampaignInstallationThreatCase scriptedThreat = scriptedInstallationThreatForLocation(st, selected);
        CampaignForce nearest = nearestHostileCampaignForceToPoint(st, selected.x, selected.y);
        double nearestDist = nearest == null ? Double.POSITIVE_INFINITY : Math.hypot(forceMarkerX(nearest) - selected.x, forceMarkerY(nearest) - selected.y);

        if (installationThreat != null) {
            out.add("Battle Reason: tracked hostile force pressing this hub from " + hostileThreatOriginLabel(st, installationThreat));
        } else if (scriptedThreat != null) {
            out.add("Battle Reason: infiltration warning from " + scriptedThreat.origin);
        } else if (selected.type == CampaignLocationType.ENEMY_ACTIVITY || isForcedCombatCampaignMission(selected)) {
            out.add("Battle Reason: hostile-held objective or garrison controls this site.");
        } else if (nearest != null && nearestDist <= 520.0) {
            out.add("Battle Reason: " + nearest.name + " is close enough to interfere.");
        } else {
            out.add("Battle Reason: no battle expected unless a tracked contact closes.");
        }

        if (!selected.services.isEmpty() || selected.type == CampaignLocationType.REPAIR_SITE) {
            if (installationThreat != null || scriptedThreat != null || nearestDist <= 420.0) {
                out.add("Hub Safety: THREATENED  |  hostile force inside the defense ring.");
            } else if (nearestDist <= 900.0) {
                out.add("Hub Safety: WATCHED  |  hostile force near approach lanes.");
            } else {
                out.add("Hub Safety: SAFE  |  no hostile force nearby.");
            }
        }

        if (nearest != null) {
            String trend = nearestDist <= 300.0 ? "DANGER HIGH"
                    : (nearestDist <= 650.0 ? "DANGER RISING"
                    : (nearestDist <= 1100.0 ? "DANGER BUILDING" : "DANGER LOW"));
            out.add("Danger Trend: " + trend + "  |  nearest force " + (int) Math.round(nearestDist) + " out.");
        } else {
            out.add("Danger Trend: DANGER LOW  |  no hostile force track nearby.");
        }

        String hidden = hiddenThreatHintLine(st, selected);
        if (!hidden.isBlank()) out.add(hidden);
        while (out.size() > 4) out.remove(out.size() - 1);
        return out;
    }

    public static List<String> compactRouteAssessmentLines(GameContext ctx) {
        CampaignState st = state(ctx);
        CampaignLocation selected = selectedCampaignLocation(ctx);
        CampaignLocation current = currentCampaignLocation(ctx);
        if (ctx == null || st == null || selected == null) return List.of();
        ensureGalaxyFleetPosition(st, current);
        GalaxyRouteAssessment assessment = analyzeRoute(st, ctx, st.playerGalaxyX, st.playerGalaxyY, selected);
        ArrayList<String> out = new ArrayList<>();
        out.add("Route: " + routeTempoLabel(assessment) + "  |  ETA " + (int) Math.ceil(assessment.durationSec) + "s");
        out.add("Risk: " + routeExposureLabel(assessment) + "  |  " + (int) Math.round(assessment.interceptionRisk) + "%");
        out.add("Support: " + routeLogisticsLabel(assessment) + "  |  Intel " + campaignIntelReadout(ctx));
        List<String> warnings = routeForceWarningLines(ctx, st.playerGalaxyX, st.playerGalaxyY, selected.x, selected.y);
        if (!warnings.isEmpty()) out.add(warnings.get(0));
        return out;
    }

    private static List<String> freeTravelSelectionLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !hasSelectedFreeTravelTarget(ctx)) return List.of("No location selected.");
        ensureGalaxyFleetPosition(st, currentCampaignLocation(ctx));
        double targetX = selectedFreeTravelTargetX(ctx);
        double targetY = selectedFreeTravelTargetY(ctx);
        GalaxyRouteAssessment assessment = analyzeRouteToPoint(st, ctx, st.playerGalaxyX, st.playerGalaxyY, targetX, targetY, 0.18);
        ArrayList<String> out = new ArrayList<>();
        out.add("Type: FREE COURSE");
        out.add("Alignment: Unrestricted navigation");
        out.add("Threat: " + routeExposureLabel(assessment));
        out.add("Docking: Open space");
        out.add("Fleet Order: " + campaignFleetPostureReadout(ctx));
        CampaignAction primaryAction = campaignPrimaryAction(ctx);
        if (primaryAction != null && !primaryAction.label.isBlank()) out.add("Primary Recommendation: " + primaryAction.label);
        out.add("Available Actions: " + campaignVisibleActions(ctx).size());
        out.add("Route: " + routeTempoLabel(assessment) + "  |  ETA " + (int) Math.ceil(assessment.durationSec) + "s");
        out.add("Risk: " + routeExposureLabel(assessment) + "  |  " + (int) Math.round(assessment.interceptionRisk) + "%");
        out.add("Support: " + routeLogisticsLabel(assessment) + "  |  Intel " + campaignIntelReadout(ctx));
        out.add("Region Note: " + regionIdentitySummaryFor(ctx, targetX, targetY));
        out.add("Free-travel target at X " + (int) Math.round(targetX) + "  Y " + (int) Math.round(targetY));
        return out;
    }

    private static List<String> selectedContactSidebarLines(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !hasSelectedCampaignContactTarget(ctx)) return List.of("No contact selected.");
        ArrayList<String> out = new ArrayList<>();
        out.add("Type: " + (selectedCampaignContactHostile(ctx) ? "HOSTILE CONTACT" : "TRACKED CONTACT"));
        out.add("Alignment: " + (selectedCampaignContactHostile(ctx) ? "Hostile" : "Unknown"));
        String intel = selectedCampaignContactIntelLabel(ctx);
        if (!intel.isBlank()) out.add("Intel State: " + intel);
        out.add("Fleet Order: " + campaignFleetPostureReadout(ctx));
        out.add("Why It Matters: hostile contact selected on the map");
        out.add(selectedContactOpportunityLine(ctx));
        out.add(selectedContactConsequenceLine(ctx));
        out.add(selectedContactRiskLine(ctx));
        CampaignAction primaryAction = campaignPrimaryAction(ctx);
        if (primaryAction != null && !primaryAction.label.isBlank()) out.add("Primary Recommendation: " + primaryAction.label);
        out.add("Available Actions: " + campaignVisibleActions(ctx).size());
        String subtitle = selectedCampaignContactSubtitle(ctx);
        if (!subtitle.isBlank()) out.add("Contact Detail: " + subtitle);
        String scanDetail = selectedContactScanDetailLine(ctx);
        if (!scanDetail.isBlank()) out.add(scanDetail);
        CampaignForce force = campaignForceBySelectedContact(ctx);
        if (force != null) {
            out.add("Force Owner: " + force.name);
            out.add("Force Type: " + campaignForceKindLabel(force.kind)
                    + "  |  " + campaignForceContactLabel(force)
                    + "  |  confidence " + (int) Math.round(force.contactConfidence * 100.0) + "%");
            out.add("Force Orders: " + campaignForceBehaviorReadout(force)
                    + "  |  " + campaignForceDirectionLabel(force)
                    + "  |  strength " + (int) Math.round(force.strength));
            if (force.contactState == CampaignForceContactState.STALE) {
                out.add("Contact Break: " + campaignForceLostContactReadout(st, force));
            }
        }
        out.add("Coordinates: X " + (int) Math.round(ctx.ui.selectedCampaignContactX)
                + "  Y " + (int) Math.round(ctx.ui.selectedCampaignContactY));
        return out;
    }

    public static String selectedStrategicDestinationLabel(GameContext ctx) {
        CampaignLocation selected = selectedCampaignLocation(ctx);
        if (selected != null) return selected.name;
        if (hasSelectedFreeTravelTarget(ctx)) {
            return "FREE COURSE X " + (int) Math.round(selectedFreeTravelTargetX(ctx))
                    + "  Y " + (int) Math.round(selectedFreeTravelTargetY(ctx));
        }
        return "None selected";
    }

    private static FleetCommitment resolveFleetCommitment(String raw) {
        if (raw != null) {
            try {
                return FleetCommitment.valueOf(raw.trim().toUpperCase(Locale.US));
            } catch (Exception ignored) {
                // Fall through.
            }
        }
        return FleetCommitment.AUTO;
    }

    private static String fleetCommitmentLabel(FleetCommitment commitment) {
        return switch ((commitment == null) ? FleetCommitment.AUTO : commitment) {
            case AUTO -> "AUTO";
            case COMMIT -> "COMMIT";
            case HOLD_BACK -> "HOLD BACK";
            case RESERVE -> "RESERVE";
        };
    }

    private static String fleetCommitmentDetail(FleetCommitment commitment) {
        return switch ((commitment == null) ? FleetCommitment.AUTO : commitment) {
            case AUTO -> "Follows command-group default and current readiness.";
            case COMMIT -> "Forces this hull into next tactical entry if operational.";
            case HOLD_BACK -> "Keeps this hull out of the next tactical entry by order.";
            case RESERVE -> "Delays this hull for reinforcement arrival after contact begins.";
        };
    }

    private static PersistentFleetEntry campaignFleetFocusEntry(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.ui == null || st.persistentBlueFleet.isEmpty()) return null;
        int focusSlotId = ctx.ui.campaignFleetFocusSlotId;
        PersistentFleetEntry focused = persistentFleetEntryBySlotId(st, focusSlotId);
        if (focused != null && !focused.destroyed) return focused;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            ctx.ui.campaignFleetFocusSlotId = entry.slotId;
            return entry;
        }
        ctx.ui.campaignFleetFocusSlotId = -1;
        return null;
    }

    private static boolean cycleCampaignFleetFocus(GameContext ctx, int dir) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.ui == null || st.persistentBlueFleet.isEmpty()) return false;
        ArrayList<PersistentFleetEntry> live = new ArrayList<>();
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry != null && !entry.destroyed) live.add(entry);
        }
        if (live.isEmpty()) {
            ctx.ui.campaignFleetFocusSlotId = -1;
            return false;
        }
        int currentIndex = 0;
        for (int i = 0; i < live.size(); i++) {
            if (live.get(i).slotId == ctx.ui.campaignFleetFocusSlotId) {
                currentIndex = i;
                break;
            }
        }
        int next = Math.floorMod(currentIndex + ((dir < 0) ? -1 : 1), live.size());
        ctx.ui.campaignFleetFocusSlotId = live.get(next).slotId;
        EventSystem.showBanner(ctx, "FLEET FOCUS: " + displayPersistentFleetEntryName(live.get(next)).toUpperCase(Locale.US), 1.0);
        return true;
    }

    private static boolean setCampaignFleetCommitment(GameContext ctx, FleetCommitment commitment) {
        CampaignState st = state(ctx);
        PersistentFleetEntry entry = campaignFleetFocusEntry(ctx);
        if (ctx == null || st == null || entry == null || commitment == null) return false;
        entry.tacticalCommitmentId = commitment.name();
        entry.tacticalAbsenceReason = "";
        EventSystem.showBanner(ctx,
                (displayPersistentFleetEntryName(entry) + "  |  " + fleetCommitmentLabel(commitment)).toUpperCase(Locale.US),
                1.2);
        return true;
    }

    private static boolean assignCampaignFleetFocusToFlagGroup(GameContext ctx) {
        CampaignState st = state(ctx);
        PersistentFleetEntry entry = campaignFleetFocusEntry(ctx);
        if (ctx == null || st == null || entry == null) return false;
        entry.commandGroupId = CAMPAIGN_FLAGSHIP_COMMAND_GROUP;
        rebalancePersistentCommandGroups(st);
        EventSystem.showBanner(ctx, (displayPersistentFleetEntryName(entry) + "  |  FLAG GROUP").toUpperCase(Locale.US), 1.1);
        return true;
    }

    private static boolean assignCampaignFleetFocusToDetachGroup(GameContext ctx) {
        CampaignState st = state(ctx);
        PersistentFleetEntry entry = campaignFleetFocusEntry(ctx);
        if (ctx == null || st == null || entry == null) return false;
        int bestGroup = bestPersistentCommandGroupForEntry(st, entry);
        if (bestGroup == CAMPAIGN_FLAGSHIP_COMMAND_GROUP) {
            EventSystem.showBanner(ctx, "NO DETACHMENT ANCHOR AVAILABLE FOR THAT HULL", 1.2);
            return false;
        }
        entry.commandGroupId = bestGroup;
        rebalancePersistentCommandGroups(st);
        EventSystem.showBanner(ctx, (displayPersistentFleetEntryName(entry) + "  |  DETACHMENT " + bestGroup).toUpperCase(Locale.US), 1.1);
        return true;
    }

    public static List<String> campaignFleetManagerLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("Fleet data unavailable.");
        int hulls = 0;
        int damaged = 0;
        int carriers = 0;
        int logistics = 0;
        int heavy = 0;
        double avgHull = 0.0;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            hulls++;
            avgHull += MathUtil.clamp(entry.hullConditionFrac, 0.0, 1.0);
            if (entry.hullConditionFrac < 0.82 || entry.shieldConditionFrac < 0.82) damaged++;
            if (entry.role == ShipRole.CARRIER || entry.role == ShipRole.DRONE_CARRIER || entry.role == ShipRole.CARRIER_SUPPORT_TITAN) carriers++;
            if (entry.role == ShipRole.HAULER || entry.role == ShipRole.MINER || entry.role == ShipRole.TRANSPORT_TITAN) logistics++;
            if (entry.role == ShipRole.BATTLESHIP || entry.role == ShipRole.DREADNOUGHT || entry.role == ShipRole.SUPERSHIP
                    || entry.role == ShipRole.BULWARK_TITAN || entry.role == ShipRole.ARTILLERY_TITAN) heavy++;
        }
        avgHull = (hulls <= 0) ? 1.0 : avgHull / hulls;
        int flagshipGroup = 0;
        int detachedGroups = 0;
        int committed = 0;
        int heldBack = 0;
        int reserve = 0;
        java.util.LinkedHashSet<Integer> groupIds = new java.util.LinkedHashSet<>();
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            int groupId = Math.max(CAMPAIGN_FLAGSHIP_COMMAND_GROUP, entry.commandGroupId);
            groupIds.add(groupId);
            if (groupId == CAMPAIGN_FLAGSHIP_COMMAND_GROUP) flagshipGroup++;
            else detachedGroups++;
            FleetCommitment commitment = resolveFleetCommitment(entry.tacticalCommitmentId);
            if (commitment == FleetCommitment.COMMIT) committed++;
            if (commitment == FleetCommitment.HOLD_BACK) heldBack++;
            if (commitment == FleetCommitment.RESERVE) reserve++;
        }
        PersistentFleetEntry focused = campaignFleetFocusEntry(ctx);
        ArrayList<String> out = new ArrayList<>();
        out.add("Fleet orders here affect which stored hulls join the next tactical contact.");
        out.add("Command Hulls: " + hulls + "  |  Damaged " + damaged);
        out.add("Next Tactical Entry: Flag Group " + flagshipGroup + "  |  Detached " + detachedGroups);
        out.add("Overmap Berths: in-world roster hulls are stored until tactical contact.");
        out.add("Force Mix: Heavy " + heavy + "  |  Carriers " + carriers + "  |  Logistics " + logistics);
        out.add("Commitments: Commit " + committed + "  |  Reserve " + reserve + "  |  Hold " + heldBack);
        out.addAll(tacticalDeploymentPreviewLines(ctx));
        out.add("Average Hull Condition: " + (int) Math.round(avgHull * 100.0) + "%  |  Command Groups " + Math.max(1, groupIds.size()));
        out.add("Flagship Capability: Mothership deck can launch picket escorts.");
        out.addAll(StretchGoalsFleetDoctrineSystem.commandBoardLines(st.fleetDoctrineExpansion));
        out.addAll(campaignYardDocketLines(ctx, 3));
        if (focused != null) {
            out.add("Focused Hull: " + displayPersistentFleetEntryName(focused)
                    + "  |  " + roleDisplayName(focused.role).toUpperCase(Locale.US)
                    + "  |  " + fleetCommitmentLabel(resolveFleetCommitment(focused.tacticalCommitmentId)));
        } else {
            out.add("Command State: " + campaignFleetStrainReadout(ctx));
        }
        int shown = 0;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            out.add(displayPersistentFleetEntryName(entry) + "  |  "
                    + entry.role.name().replace('_', ' ') + "  |  HULL "
                    + (int) Math.round(MathUtil.clamp(entry.hullConditionFrac, 0.0, 1.0) * 100.0) + "%  |  "
                    + campaignCargoLabelForPersistentEntry(entry) + "  |  "
                    + fleetCommitmentLabel(resolveFleetCommitment(entry.tacticalCommitmentId)));
            if (++shown >= 3) break;
        }
        return out;
    }

    public static List<String> campaignFleetBoardSummaryLines(GameContext ctx) {
        ensureStrategicOvermapReady(ctx);
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return List.of("No fleet data.");
        int ready = 0;
        int strained = 0;
        int support = 0;
        int escorts = 0;
        int capitals = 0;
        int detached = 0;
        int recovered = 0;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            double hull = MathUtil.clamp(entry.hullConditionFrac, 0.0, 1.0);
            double shield = MathUtil.clamp(entry.shieldConditionFrac, 0.0, 1.0);
            if (hull >= 0.86 && shield >= 0.80) ready++;
            if (hull < 0.70 || shield < 0.62) strained++;
            if (entry.commandGroupId != CAMPAIGN_FLAGSHIP_COMMAND_GROUP) detached++;
            if (entry.role == ShipRole.HAULER || entry.role == ShipRole.MINER || entry.role == ShipRole.TRANSPORT
                    || entry.role == ShipRole.TRANSPORT_TITAN || entry.role == ShipRole.MOBILE_STATION_TITAN) {
                support++;
            } else if (entry.role == ShipRole.BATTLESHIP || entry.role == ShipRole.DREADNOUGHT
                    || entry.role == ShipRole.SUPERSHIP || entry.role == ShipRole.BATTLECRUISER
                    || entry.role == ShipRole.BULWARK_TITAN || entry.role == ShipRole.ARTILLERY_TITAN) {
                capitals++;
            } else {
                escorts++;
            }
            String name = (entry.name == null) ? "" : entry.name.toUpperCase(Locale.US);
            if (name.contains("RECOVERED") || name.contains("RELAY") || name.contains("DISTRESS") || name.contains("CRADLE")) {
                recovered++;
            }
        }
        return List.of(
                "READY " + ready + "  |  STRAINED " + strained,
                "ESCORTS " + escorts + "  |  SUPPORT " + support + "  |  CAPITALS " + capitals,
                "DETACHED " + detached + "  |  RECOVERED " + recovered
        );
    }

    public static boolean cyclePreBattleFormation(GameContext ctx) {
        if (ctx == null || ctx.command == null) return false;
        GameContext.FleetFormation[] values = GameContext.FleetFormation.values();
        GameContext.FleetFormation current = ctx.command.alliedFleetFormation == null
                ? GameContext.FleetFormation.WEDGE
                : ctx.command.alliedFleetFormation;
        int next = Math.floorMod(current.ordinal() + 1, values.length);
        ctx.command.alliedFleetFormation = values[next];
        EventSystem.showBanner(ctx, "PRE-BATTLE FORMATION: " + ctx.command.alliedFleetFormation.name(), 1.1);
        return true;
    }

    public static boolean activateProtectFlagshipObjective(GameContext ctx, double minHullFrac) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.player == null) return false;
        st.protectFlagshipObjectiveActive = true;
        st.protectFlagshipStartHp = Math.max(1, ctx.player.hp);
        st.protectFlagshipMinHullFrac = MathUtil.clamp(minHullFrac, 0.08, 0.90);
        EventSystem.showBanner(ctx, "OBJECTIVE: PROTECT FLAGSHIP", 1.2);
        return true;
    }

    public static boolean activateEmergencyExtractionObjective(GameContext ctx, Ship target, double holdSec) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || target == null) return false;
        if (!target.alive || target.dying || target.hp <= 0) return false;
        st.emergencyExtractionObjectiveActive = true;
        st.emergencyExtractionShipId = target.id;
        st.emergencyExtractionProgressSec = 0.0;
        st.emergencyExtractionGoalSec = Math.max(2.0, holdSec);
        st.emergencyExtractionRadius = Math.max(180.0, target.radius * 4.0 + 180.0);
        EventSystem.showBanner(ctx, "OBJECTIVE: EXTRACT DISABLED SHIP", 1.2);
        return true;
    }

    public static boolean activateSalvageUnderFireObjective(GameContext ctx, double holdSec) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || st.recoverableWreckSites.isEmpty()) return false;
        for (RecoverableWreckSite site : st.recoverableWreckSites) {
            if (site == null || site.claimed) continue;
            st.salvageUnderFireObjectiveActive = true;
            st.salvageUnderFireGoalSec = Math.max(2.0, holdSec);
            site.underFireProgressSec = 0.0;
            EventSystem.showBanner(ctx, "OBJECTIVE: SALVAGE UNDER FIRE", 1.2);
            return true;
        }
        return false;
    }

    public static boolean activateConvoyLaneDefenseObjective(GameContext ctx, int requiredSurvivors) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null) return false;
        ArrayList<Ship> convoyAssets = new ArrayList<>();
        for (Ship ship : ctx.ships) {
            if (!isCivilianConvoyAsset(ship)) continue;
            convoyAssets.add(ship);
        }
        if (convoyAssets.isEmpty()) return false;

        st.objectiveAssetIds.clear();
        st.objectiveAssetTotal = 0;
        st.objectiveAssetLosses = 0;
        st.lastAnnouncedObjectiveAssetLosses = 0;
        st.objectiveAssetLabel = "CIVILIAN CONVOYS";
        for (Ship asset : convoyAssets) {
            registerObjectiveAsset(st, asset);
        }
        int required = MathUtil.clamp(requiredSurvivors, 1, Math.max(1, st.objectiveAssetTotal));
        registerObjectiveAssetQuota(st, required, "DEFEAT: CIVILIAN CONVOY LANE BROKEN");
        st.convoyLaneDefenseObjectiveActive = true;
        st.civilianTrafficConstraintActive = true;
        EventSystem.showBanner(ctx, "OBJECTIVE: DEFEND CIVILIAN CONVOY LANE", 1.3);
        return true;
    }

    private static boolean isCivilianConvoyAsset(Ship ship) {
        if (ship == null || !ship.alive || ship.dying || ship.hp <= 0) return false;
        if (ship.faction == Faction.ENEMY) return false;
        if (ship instanceof Player) return false;
        if (ship.role == ShipRole.TRANSPORT || ship.role == ShipRole.HAULER
                || ship.role == ShipRole.TRANSPORT_TITAN || ship.role == ShipRole.MINER) {
            return true;
        }
        String name = ship.name == null ? "" : ship.name.toUpperCase(Locale.US);
        return name.contains("CONVOY") || name.contains("CIVILIAN") || name.contains("LINER")
                || name.contains("TENDER") || name.contains("BARGE") || name.contains("TRAM")
                || name.contains("SKIFF") || name.contains("RUNNER");
    }

    public static boolean activateMinefieldBreachObjective(GameContext ctx, List<double[]> routePoints, double holdSec) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.player == null || routePoints == null || routePoints.isEmpty()) return false;
        st.minefieldBreachRoutePoints.clear();
        for (double[] point : routePoints) {
            if (point == null || point.length < 2) continue;
            double x = point[0];
            double y = point[1];
            if (!Double.isFinite(x) || !Double.isFinite(y)) continue;
            st.minefieldBreachRoutePoints.add(new double[]{
                    GameMath.clamp(x, CAMPAIGN_POCKET_MARGIN, ctx.WORLD_W - CAMPAIGN_POCKET_MARGIN),
                    GameMath.clamp(y, CAMPAIGN_POCKET_MARGIN, ctx.WORLD_H - CAMPAIGN_POCKET_MARGIN)
            });
        }
        if (st.minefieldBreachRoutePoints.isEmpty()) return false;
        st.minefieldBreachObjectiveActive = true;
        st.minefieldBreachRouteIndex = 0;
        st.minefieldBreachProgressSec = 0.0;
        st.minefieldBreachHoldSec = Math.max(1.0, holdSec);
        st.minefieldBreachRadius = Math.max(150.0, ctx.player.radius * 2.6);
        st.objectiveType = ObjectiveType.SURVIVE;
        st.objectiveLabel = "Breach minefield along planned route";
        st.objectiveProgress = 0.0;
        st.objectiveGoal = Math.max(1.0, st.minefieldBreachRoutePoints.size());
        spawnMinefieldBreachAnchors(ctx, st);
        EventSystem.showBanner(ctx, "OBJECTIVE: BREACH MINEFIELD ROUTE", 1.3);
        return true;
    }

    public static boolean activatePursuitObjective(GameContext ctx, Ship target,
                                                   double escapeX, double escapeY,
                                                   double escapeRadius, double disableHoldSec) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || target == null) return false;
        if (!target.alive || target.dying || target.hp <= 0) return false;
        st.pursuitObjectiveActive = true;
        st.pursuitTargetShipId = target.id;
        st.pursuitEscapeX = GameMath.clamp(escapeX, CAMPAIGN_POCKET_MARGIN, ctx.WORLD_W - CAMPAIGN_POCKET_MARGIN);
        st.pursuitEscapeY = GameMath.clamp(escapeY, CAMPAIGN_POCKET_MARGIN, ctx.WORLD_H - CAMPAIGN_POCKET_MARGIN);
        st.pursuitEscapeRadius = Math.max(160.0, escapeRadius);
        st.pursuitDisableProgressSec = 0.0;
        st.pursuitDisableHoldSec = Math.max(0.75, disableHoldSec);
        st.objectiveType = ObjectiveType.DESTROY;
        st.objectiveLabel = "Pursue target before it escapes";
        st.objectiveProgress = 0.0;
        st.objectiveGoal = 1.0;
        st.bossTargetId = target.id;
        EventSystem.showBanner(ctx, "OBJECTIVE: PURSUE ESCAPING TARGET", 1.3);
        return true;
    }

    public static boolean activateRetreatCorridorObjective(GameContext ctx,
                                                           double corridorX, double corridorY,
                                                           double corridorRadius, double holdSec) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || ctx.player == null) return false;
        st.retreatCorridorObjectiveActive = true;
        st.retreatCorridorX = GameMath.clamp(corridorX, CAMPAIGN_POCKET_MARGIN, ctx.WORLD_W - CAMPAIGN_POCKET_MARGIN);
        st.retreatCorridorY = GameMath.clamp(corridorY, CAMPAIGN_POCKET_MARGIN, ctx.WORLD_H - CAMPAIGN_POCKET_MARGIN);
        st.retreatCorridorRadius = Math.max(150.0, corridorRadius);
        st.retreatCorridorProgressSec = 0.0;
        st.retreatCorridorHoldSec = Math.max(1.0, holdSec);
        st.objectiveType = ObjectiveType.SURVIVE;
        st.objectiveLabel = "Retreat through survival corridor";
        st.objectiveProgress = 0.0;
        st.objectiveGoal = st.retreatCorridorHoldSec;
        EventSystem.showBanner(ctx, "OBJECTIVE: RETREAT CORRIDOR", 1.3);
        return true;
    }

    public static List<String> shipSpecificRetreatThresholdLines(GameContext ctx) {
        if (ctx == null || ctx.ships == null) return List.of();
        ArrayList<String> out = new ArrayList<>();
        for (Ship ship : ctx.ships) {
            if (ship == null || ship.faction == Faction.ENEMY || ship instanceof Player) continue;
            String label = (ship.name == null || ship.name.isBlank()) ? roleDisplayName(ship.role) : ship.name;
            out.add(label + "  |  retreat at " + shipRetreatThresholdPercent(ship) + "% hull"
                    + "  |  " + shipRetreatReason(ship));
        }
        return out;
    }

    private static int shipRetreatThresholdPercent(Ship ship) {
        if (ship == null) return 40;
        return switch (ship.role) {
            case TRANSPORT, HAULER, MINER, TRANSPORT_TITAN -> 62;
            case CARRIER, DRONE_CARRIER -> 48;
            case BATTLESHIP, DREADNOUGHT, BATTLECRUISER, SUPERSHIP, BULWARK_TITAN,
                    CARRIER_SUPPORT_TITAN, VANGUARD_TITAN, INTERDICTION_TITAN,
                    COMMAND_INTEL_TITAN, BOARDING_RECOVERY_TITAN, ARTILLERY_TITAN,
                    SHIELD_BASTION_TITAN, FLEET_TELEPORTER_TITAN, ELITE_SUPERSHIP_COMMAND_TITAN,
                    ELITE_REINFORCEMENTS_TITAN, MOBILE_STATION_TITAN, HYPERWEAPON_TITAN,
                    MOTHERSHIP -> 30;
            case BOMBER, STEALTH_SHIP, MISSILE_BOAT -> 42;
            default -> 38;
        };
    }

    private static String shipRetreatReason(Ship ship) {
        if (ship == null) return "standard doctrine";
        return switch (ship.role) {
            case TRANSPORT, HAULER, MINER, TRANSPORT_TITAN -> "cargo / civilian value";
            case CARRIER, DRONE_CARRIER -> "flight-deck preservation";
            case BATTLESHIP, DREADNOUGHT, BATTLECRUISER, SUPERSHIP, BULWARK_TITAN,
                    CARRIER_SUPPORT_TITAN, VANGUARD_TITAN, INTERDICTION_TITAN,
                    COMMAND_INTEL_TITAN, BOARDING_RECOVERY_TITAN, ARTILLERY_TITAN,
                    SHIELD_BASTION_TITAN, FLEET_TELEPORTER_TITAN, ELITE_SUPERSHIP_COMMAND_TITAN,
                    ELITE_REINFORCEMENTS_TITAN, MOBILE_STATION_TITAN, HYPERWEAPON_TITAN,
                    MOTHERSHIP -> "capital armor reserve";
            case BOMBER, STEALTH_SHIP, MISSILE_BOAT -> "strike craft survival";
            default -> "line combat doctrine";
        };
    }

