    private static String campaignSiteMemorySubtitle(CampaignLocation location) {
        if (location == null) return "Survey complete";
        if (location.type == CampaignLocationType.REPAIR_SITE) {
            return location.completed
                    ? "Serviced anchorage  |  fleet support has recently cycled through here"
                    : "Repair anchorage  |  fleet service available";
        }
        String base = switch (location.type) {
            case RESOURCE_ZONE -> "Survey complete  |  ore pocket stripped and navigation notes logged";
            case SALVAGE_FIELD -> "Survey complete  |  wreck sweep finished and black boxes removed";
            case HIDDEN_CACHE -> "Survey complete  |  hidden stores recovered and site opened";
            case DISTRESS_SIGNAL -> "Survey complete  |  rescue contact stabilized and the channel went quiet";
            case STORY_EVENT -> "Survey complete  |  relay traffic decoded and the ghost channel collapsed";
            case ENEMY_ACTIVITY -> "Survey complete  |  hostile pocket mapped after action";
            case MAIN_MISSION -> "Mission secured  |  site remains under campaign control";
            default -> "Survey complete  |  contact resolved";
        };
        if (!location.consumed && !location.completed) base = location.detail;
        String route = campaignRouteStateLine(location);
        if (!route.isBlank()) return base + "  |  " + route;
        String scar = campaignScarLine(location);
        if (!scar.isBlank()) return base + "  |  " + scar;
        return base;
    }

    private static String dockingStatusReadout(GameContext ctx, CampaignLocation location) {
        if (ctx == null || location == null) return "Unknown";
        if (isDockedAtSelectedLocation(ctx)) return "IN RANGE";
        CampaignState st = state(ctx);
        if (st == null) return "APPROACH REQUIRED";
        double distance = Math.hypot(st.playerGalaxyX - location.x, st.playerGalaxyY - location.y);
        return "APPROACH " + (int) Math.round(distance);
    }

    private static void maintainStrategicOvermapView(GameContext ctx, CampaignState st) {
        if (ctx == null || ctx.ui == null || st == null || !isStrategicOvermapMode(st) || ctx.gameOver) return;
        if (ctx.ui.shopOpen || ctx.ui.baseMenuOpen || ctx.ui.powerManagementOpen
                || ctx.ui.crewStationsOpen || ctx.ui.flightDeckOpen || ctx.ui.strategicEncounterPrompt.active) {
            return;
        }
        ctx.ui.mapOpen = true;
        if (ctx.state != GameState.GAME_OVER) {
            ctx.state = GameState.MAP;
        }
    }

    private static boolean hasLiveHostilePresenceInPlayerPocket(GameContext ctx, CampaignState st) {
        if (ctx == null || st == null || ctx.player == null) return false;
        int playerSubzone = currentLoadedMissionSubzone(ctx);
        if (playerSubzone < 0) {
            playerSubzone = missionSubzoneForPoint(ctx, st.sector, ctx.player.x, ctx.player.y);
        }
        for (Ship ship : ctx.ships) {
            if (ship == null || ship == ctx.player) continue;
            if (!ship.alive || ship.dying || ship.hp <= 0) continue;
            if (ship.faction == null || ship.faction.isFriendlyTo(ctx.player.faction)) continue;
            int shipSubzone = missionSubzoneForPoint(ctx, st.sector, ship.x, ship.y);
            if (shipSubzone == playerSubzone) return true;
        }
        return false;
    }

    private static void enterStrategicOvermap(GameContext ctx, CampaignState st, String banner) {
        if (ctx == null || ctx.ui == null || st == null || !isStrategicOvermapMode(st) || ctx.gameOver) return;
        syncPersistentFleetEntrySnapshots(ctx, st);
        clearBattleEncounterWorld(ctx);
        resetPersistentFleetSpawnHandles(st);
        ctx.ui.shopOpen = false;
        ctx.ui.baseMenuOpen = false;
        ctx.ui.powerManagementOpen = false;
        ctx.ui.crewStationsOpen = false;
        ctx.ui.flightDeckOpen = false;
        ctx.ui.mapOpen = true;
        ctx.ui.strategicMapZoom = Math.max(2.2, ctx.ui.strategicMapZoom);
        CampaignLocation current = currentCampaignLocation(ctx);
        if (current != null) {
            ctx.ui.strategicMapFocusX = current.x;
            ctx.ui.strategicMapFocusY = current.y;
        }
        ctx.state = GameState.MAP;
        if (banner != null && !banner.isBlank()) {
            EventSystem.showBanner(ctx, banner + "  |  STRATEGIC MAP ONLINE", 2.2);
        }
    }

    private static void activateStrategicOvermapLayer(GameContext ctx, CampaignState st, String banner) {
        if (ctx == null || st == null) return;
        st.strategicOvermapMode = true;
        st.manualEncounterCommitInProgress = false;
        st.objectiveSecured = false;
        st.awaitingEpisodeLaunch = false;
        st.pendingEpisodeSector = 0;
        st.awaitingFleetHubChoice = false;
        st.fleetHubChoiceTimer = 0.0;
        st.transitionTimer = 0.0;
        st.routeChoices.clear();
        st.selectedRouteChoice = 0;
        st.routeArrivalSourceSector = 0;
        st.authoredObjectiveHostiles.clear();
        st.authoredObjectiveKills = 0;
        st.objectiveAssetIds.clear();
        st.objectiveAssetTotal = 0;
        st.objectiveAssetLosses = 0;
        st.objectiveAssetRequiredSurvivors = 0;
        st.objectiveAssetFailureText = "";
        st.convoyLaneDefenseObjectiveActive = false;
        st.civilianTrafficConstraintActive = false;
        clearMinefieldBreachObjective(st);
        clearPursuitObjective(st);
        clearRetreatCorridorObjective(st);
        st.sideObjectiveType = SideObjectiveType.NONE;
        st.sideObjectiveLabel = "";
        st.sideObjectiveGoal = 0.0;
        st.sideObjectiveProgress = 0.0;
        st.sideObjectiveCompleted = false;
        st.sideObjectiveFailed = false;
        configureStrategicOvermapTheater(ctx, st, scriptFor(Math.max(1, st.sector)));
        applySectorModifiers(ctx, st, scriptFor(Math.max(1, st.sector)));
        ctx.enemyWaveTimer = Double.POSITIVE_INFINITY;
        if (ctx.ui != null) {
            ctx.ui.clearStrategicEncounterPrompt();
            ctx.ui.clearCampaignHubMenu();
        }
        enterStrategicOvermap(ctx, st, banner);
    }

    private static void clearBattleEncounterWorld(GameContext ctx) {
        if (ctx == null) return;
        ctx.projectiles.clear();
        ctx.salvage.clear();
        ctx.asteroids.clear();
        ctx.lockedTarget = null;
        ctx.enemyBase = null;
        ctx.allyBase = null;
        ctx.teamBases.clear();
        ctx.ships.removeIf(ship -> ship != null && ship != ctx.player);
        if (ctx.player != null) {
            ctx.player.vx = 0.0;
            ctx.player.vy = 0.0;
            ctx.player.resetWeaponCycleState();
        }
        VFX.clearAll();
        Explosion.active.clear();
        WreckChunk.clearAll();
        FogOfWarSystem.reset(ctx);
    }

    private static void prepareGalaxySearchGroupEncounterWorld(GameContext ctx, CampaignState st, GalaxySearchGroup group) {
        if (ctx == null || st == null || group == null || ctx.player == null) return;
        TacticalApproachDirection hostileApproach = hostileSearchGroupApproachDirection(st, group);
        clearBattleEncounterWorld(ctx);
        clearLocalEncounterMapIdentity(st);
        positionPlayerForOpenSpaceFleetClash(ctx, st, oppositeApproachDirection(hostileApproach));
        resetPersistentFleetSpawnHandles(st);
        spawnPersistentBlueFleet(ctx, st);
        spawnCoalitionSupportFleet(ctx, st);
        seedBaselineCampaignForceOwnership(ctx, st);
        syncCampaignForceSimulationSeeds(ctx, st);

        st.sectorElapsed = 0.0;
        st.objectiveSecured = false;
        st.transitionTimer = 0.0;
        st.awaitingEpisodeLaunch = false;
        st.pendingEpisodeSector = 0;
        st.awaitingFleetHubChoice = false;
        st.fleetHubChoiceTimer = 0.0;
        st.routeChoices.clear();
        st.selectedRouteChoice = 0;
        st.routeArrivalSourceSector = 0;
        st.knownHostiles.clear();
        st.authoredObjectiveHostiles.clear();
        st.authoredObjectiveKills = 0;
        st.objectiveAssetIds.clear();
        st.objectiveAssetTotal = 0;
        st.objectiveAssetLosses = 0;
        st.objectiveAssetRequiredSurvivors = 0;
        st.objectiveAssetFailureText = "";
        st.convoyLaneDefenseObjectiveActive = false;
        st.civilianTrafficConstraintActive = false;
        clearMinefieldBreachObjective(st);
        clearPursuitObjective(st);
        clearRetreatCorridorObjective(st);
        st.sideObjectiveType = SideObjectiveType.NONE;
        st.sideObjectiveLabel = "";
        st.sideObjectiveGoal = 0.0;
        st.sideObjectiveProgress = 0.0;
        st.sideObjectiveCompleted = false;
        st.sideObjectiveFailed = false;
        st.extractionMinHoldSeconds = 0.0;
        st.sectorTimeLimit = 0.0;
        st.enemyBaseWinConditionActive = false;
        st.objectivePhaseLabel = "FLEET CLASH: Left allied spawn, middle neutral transit, right hostile contact   TRANSIT: Allies from west edge | Hostiles from " + approachDirectionLabel(hostileApproach);
        st.threatStateLabel = "OPEN-SPACE FLEET CLASH: no landmark assault, no authored mission blockers   VECTOR: Hostile intercept approaching from " + approachDirectionLabel(hostileApproach);
        st.transitionLabel = "OPEN-SPACE FLEET CLASH";
        st.transitionSummaryTop = "Friendly and hostile fleets clashed outside a landmark.";
        st.transitionSummaryBottom = "Allies spawn left, neutral space sits center, hostiles hold the right zone. Hostile ingress: " + approachDirectionLabel(hostileApproach) + ".";
        st.transitionRewardLine = "";
        st.transitionRouteImpactLine = "";

        int targetCount = spawnGalaxySearchGroupEncounterForce(ctx, st, group, hostileApproach);
        populateGalaxySearchEncounterLandmarks(ctx, st, group, hostileApproach);
        setObjective(st, ObjectiveType.DESTROY, "Break the interception", Math.max(1, targetCount));
        snapshotHostiles(ctx, st.knownHostiles);
        FogOfWarSystem.update(ctx);
        if (ctx.ui != null) {
            ctx.ui.mapOpen = false;
        }
    }

    private static void positionPlayerForOpenSpaceFleetClash(GameContext ctx, CampaignState st, TacticalApproachDirection alliedApproach) {
        if (ctx == null || st == null || ctx.player == null) return;
        int alliedZone = missionSubzoneIndex(0, 1);
        int centerZone = missionSubzoneIndex(Math.max(0, missionSubzoneColumns() / 2), 1);
        double centerX = missionSubzoneCenterX(ctx, st.sector, centerZone);
        double centerY = missionSubzoneCenterY(ctx, st.sector, centerZone);
        st.galaxyAmbientPocketCenterX = centerX;
        st.galaxyAmbientPocketCenterY = centerY;
        st.galaxyAmbientPocketRadius = openSpaceFleetClashLaneSpacing(ctx) * 1.55;
        double[] arrival = openSpaceFleetClashApproachPoint(ctx, st, -1, alliedApproach, 150.0);
        setLoadedMissionSubzone(ctx, alliedZone);
        ctx.player.x = arrival[0];
        ctx.player.y = arrival[1];
        ctx.player.vx = 0.0;
        ctx.player.vy = 0.0;
        ctx.player.angle = 0.0;
        ctx.player.campaignMissionSubzone = alliedZone;
        ctx.camX = ctx.player.x;
        ctx.camY = ctx.player.y;
    }

    private static void prepareAmbientCampaignLocationEncounterWorld(GameContext ctx, CampaignState st, CampaignLocation location) {
        if (ctx == null || st == null || location == null || ctx.player == null) return;
        CampaignInstallationThreatCase installationThreat = installationThreatCaseById(st, st.activeInstallationThreatCaseId);
        if (installationThreat == null || location.id == null || !location.id.equals(installationThreat.locationId)) {
            st.activeInstallationThreatCaseId = 0;
            installationThreat = null;
        }
        TacticalApproachDirection arrivalDirection = ambientEncounterArrivalDirection(st, location);
        TacticalApproachDirection objectiveDirection = ambientEncounterObjectiveDirection(location, arrivalDirection);
        clearBattleEncounterWorld(ctx);
        positionPlayerForAmbientEncounter(ctx, st, location);
        clearLocalEncounterMapIdentity(st);
        resetPersistentFleetSpawnHandles(st);
        spawnPersistentBlueFleet(ctx, st);
        spawnCoalitionSupportFleet(ctx, st);
        seedBaselineCampaignForceOwnership(ctx, st);
        syncCampaignForceSimulationSeeds(ctx, st);

        st.sectorElapsed = 0.0;
        st.objectiveSecured = false;
        st.transitionTimer = 0.0;
        st.awaitingEpisodeLaunch = false;
        st.pendingEpisodeSector = 0;
        st.awaitingFleetHubChoice = false;
        st.fleetHubChoiceTimer = 0.0;
        st.routeChoices.clear();
        st.selectedRouteChoice = 0;
        st.routeArrivalSourceSector = 0;
        st.knownHostiles.clear();
        st.authoredObjectiveHostiles.clear();
        st.authoredObjectiveKills = 0;
        st.objectiveAssetIds.clear();
        st.objectiveAssetTotal = 0;
        st.objectiveAssetLosses = 0;
        st.objectiveAssetRequiredSurvivors = 0;
        st.objectiveAssetFailureText = "";
        st.convoyLaneDefenseObjectiveActive = false;
        st.civilianTrafficConstraintActive = false;
        clearMinefieldBreachObjective(st);
        clearPursuitObjective(st);
        clearRetreatCorridorObjective(st);
        st.sideObjectiveType = SideObjectiveType.NONE;
        st.sideObjectiveLabel = "";
        st.sideObjectiveGoal = 0.0;
        st.sideObjectiveProgress = 0.0;
        st.sideObjectiveCompleted = false;
        st.sideObjectiveFailed = false;
        st.extractionMinHoldSeconds = 0.0;
        st.sectorTimeLimit = 0.0;
        st.enemyBaseWinConditionActive = false;
        st.galaxyAmbientSupportRequested = false;
        st.galaxyAmbientHiredShipIds.clear();
        if (installationThreat != null) {
            List<String> relevant = relevantForceNamesForLocation(st, location, 3);
            if (relevant.isEmpty()) relevant = fallbackRelevantForceNamesForLocation(st, location);
            st.objectivePhaseLabel = "INSTALLATION DEFENSE: Break the hostile intrusion and hold the harbor screen   TRANSIT: Fleet entered from "
                    + approachDirectionLabel(arrivalDirection) + " | Installation deeper on " + approachDirectionLabel(objectiveDirection);
            st.threatStateLabel = "HOSTILE INTRUSION: " + installationThreat.forceName + " approaching from " + installationThreat.origin
                    + "   VECTOR: Harbor traffic entered from " + approachDirectionLabel(arrivalDirection);
            st.transitionLabel = "INSTALLATION THREAT";
            st.transitionSummaryTop = "Installation alert. Clear the intrusion and re-open the harbor."
                    + (relevant.isEmpty() ? "" : " Forces in play: " + String.join(", ", relevant) + ".");
            st.transitionSummaryBottom = installationThreat.warning + " Friendly approach lane: "
                    + approachDirectionLabel(arrivalDirection) + ".";
        } else {
            List<String> relevant = relevantForceNamesForLocation(st, location, 3);
            if (relevant.isEmpty()) relevant = fallbackRelevantForceNamesForLocation(st, location);
            st.objectivePhaseLabel = "LOCAL SITE: Search, mine, regroup, or call support   TRANSIT: Entered from "
                    + approachDirectionLabel(arrivalDirection) + " | Site objective deeper on " + approachDirectionLabel(objectiveDirection);
            st.threatStateLabel = "SITE CONTACT: Local pocket generated from the overmap   VECTOR: Local approach lane "
                    + approachDirectionLabel(arrivalDirection);
            st.transitionLabel = "LOCAL SITE";
            st.transitionSummaryTop = "Site entered. Sweep it, exploit it, then Safe Exit."
                    + (relevant.isEmpty() ? "" : " Forces in play: " + String.join(", ", relevant) + ".");
            st.transitionSummaryBottom = "Local pocket loaded from your overmap contact. Entry vector: "
                    + approachDirectionLabel(arrivalDirection) + ".";
        }
        st.transitionRewardLine = "";
        st.transitionRouteImpactLine = "";

        populateAmbientCampaignLocationEncounter(ctx, st, location);
        List<String> finalRelevantForces = relevantForceNamesForLocation(st, location, 3);
        if (finalRelevantForces.isEmpty()) finalRelevantForces = fallbackRelevantForceNamesForLocation(st, location);
        if (finalRelevantForces.isEmpty() && (!location.services.isEmpty() || location.type == CampaignLocationType.REPAIR_SITE)) {
            finalRelevantForces = List.of(
                    ambientHubDefenseForceName(location, ambientLocationFaction(st, location)) + " (guarding)",
                    ambientHubTrafficForceName(location, ambientLocationFaction(st, location)) + " (escorting)");
        }
        if (!finalRelevantForces.isEmpty() && (st.transitionSummaryTop == null || !st.transitionSummaryTop.contains("Forces in play:"))) {
            st.transitionSummaryTop = trimmedOrFallback(st.transitionSummaryTop, "Site entered.") + " Forces in play: "
                    + String.join(", ", finalRelevantForces) + ".";
        }
        populateAmbientEncounterLandmarks(ctx, st, location);
        FogOfWarSystem.update(ctx);
        if (ctx.ui != null) {
            ctx.ui.mapOpen = false;
        }
        secureSectorObjective(ctx, "SITE OPEN - SAFE EXIT AVAILABLE");
    }

    private static void populateAmbientCampaignLocationEncounter(GameContext ctx, CampaignState st, CampaignLocation location) {
        if (ctx == null || st == null || location == null || ctx.player == null) return;
        double x = ambientEncounterCenterX(ctx, st);
        double y = ambientEncounterCenterY(ctx, st);
        TacticalApproachDirection arrivalDirection = ambientEncounterArrivalDirection(st, location);
        TacticalApproachDirection objectiveDirection = ambientEncounterObjectiveDirection(location, arrivalDirection);
        double[] routeAnchor = ambientApproachPoint(ctx, st, arrivalDirection, 0.58);
        double[] stationAnchor = ambientApproachPoint(ctx, st, objectiveDirection, 0.46);
        double[] resourceAnchor = ambientApproachPoint(ctx, st, objectiveDirection, 0.56);
        GalaxyRegionIdentity region = regionIdentityAt(ctx, location.x, location.y);
        CampaignInstallationThreatCase installationThreat = installationThreatCaseById(st, st.activeInstallationThreatCaseId);
        if (!location.services.isEmpty() || location.type == CampaignLocationType.REPAIR_SITE) {
            Faction faction = ambientLocationFaction(st, location);
            spawnCampaignAsteroidPocket(ctx, resourceAnchor[0] - 120.0, resourceAnchor[1] + 90.0, 7, 1.05, true);
            spawnCampaignAsteroidPocket(ctx, resourceAnchor[0] + 180.0, resourceAnchor[1] - 70.0, 4, 0.70, false);
            withCampaignSpawnContext(st,
                    "ambient_hub_defense",
                    campaignForceContext(
                            CampaignForceKind.BASE_DEFENSE,
                            faction,
                            ambientHubDefenseForceName(location, faction),
                            trimmedOrFallback(location.name, "Friendly installation"),
                            "Hold the installation, docks, and harbor control lattice"),
                    () -> spawnCampaignShip(ctx, ShipRole.BASE, faction, stationAnchor[0], stationAnchor[1], location.name + " Control"));
            withCampaignSpawnContext(st,
                    "ambient_hub_traffic",
                    campaignForceContext(
                            CampaignForceKind.INSTALLATION_TRAFFIC,
                            faction,
                            ambientHubTrafficForceName(location, faction),
                            trimmedOrFallback(location.name, "Friendly installation"),
                            "Run harbor traffic, dock tenders, and local service routes"),
                    () -> {
                        spawnCampaignShip(ctx, ShipRole.HAULER, faction, routeAnchor[0] + 90.0, routeAnchor[1] + 70.0, "Harbor Tender");
                        spawnCampaignShip(ctx, ShipRole.PATROL, faction, routeAnchor[0] + 260.0, routeAnchor[1] - 110.0, "Traffic Screen");
                    });
            withCampaignSpawnContext(st,
                    "ambient_hub_mining",
                    campaignForceContext(
                            CampaignForceKind.MINING_GROUP,
                            faction,
                            ambientHubMiningForceName(location, faction),
                            trimmedOrFallback(location.name, "Friendly installation"),
                            "Work nearby ore drifts and feed the installation stockpiles"),
                    () -> spawnCampaignShip(ctx, ShipRole.MINER, faction, resourceAnchor[0] - 100.0, resourceAnchor[1] + 80.0, "Traffic Prospector"));
            if (isGreenAlignedLocation(location)) {
                withCampaignSpawnContext(st,
                        "ambient_hub_defense",
                        campaignForceContext(
                                CampaignForceKind.BASE_DEFENSE,
                                faction,
                                ambientHubDefenseForceName(location, faction),
                                trimmedOrFallback(location.name, "Friendly installation"),
                                "Hold the installation, docks, and harbor control lattice"),
                        () -> {
                            spawnCampaignShip(ctx, ShipRole.FRIGATE, faction, stationAnchor[0] + 180.0, stationAnchor[1] - 90.0, "Green Watch");
                            spawnCampaignShip(ctx, ShipRole.CIWS_CORVETTE, faction, stationAnchor[0] + 110.0, stationAnchor[1] + 120.0, "Contract Flak Screen");
                            spawnCampaignShip(ctx, ShipRole.MISSILE_BOAT, faction, routeAnchor[0] + 210.0, routeAnchor[1] - 170.0, "Green Spear Boat");
                        });
            } else if (isYellowAlignedLocation(location)) {
                withCampaignSpawnContext(st,
                        "ambient_hub_traffic",
                        campaignForceContext(
                                CampaignForceKind.TRADE_GROUP,
                                faction,
                                ambientHubTrafficForceName(location, faction),
                                trimmedOrFallback(location.name, "Friendly installation"),
                                "Run broker traffic, customs lanes, and civilian exchange movement"),
                        () -> {
                            spawnCampaignShip(ctx, ShipRole.TRANSPORT, faction, routeAnchor[0] + 270.0, routeAnchor[1] - 90.0, "Yellow Liner");
                            spawnCampaignShip(ctx, ShipRole.HAULER, faction, routeAnchor[0] + 150.0, routeAnchor[1] + 110.0, "Broker Runner");
                        });
                withCampaignSpawnContext(st,
                        "ambient_hub_defense",
                        campaignForceContext(
                                CampaignForceKind.BASE_DEFENSE,
                                faction,
                                ambientHubDefenseForceName(location, faction),
                                trimmedOrFallback(location.name, "Friendly installation"),
                                "Guard customs lanes, service halos, and high-value trade traffic"),
                        () -> {
                            spawnCampaignShip(ctx, ShipRole.PICKET, faction, routeAnchor[0] + 220.0, routeAnchor[1] - 150.0, "Yellow Lane Escort");
                            if (st.sector >= 10) {
                                spawnCampaignShip(ctx, ShipRole.CARRIER, faction, stationAnchor[0] + 180.0, stationAnchor[1] + 40.0, "Yellow Deck Tender");
                            }
                        });
            } else {
                withCampaignSpawnContext(st,
                        "ambient_hub_defense",
                        campaignForceContext(
                                CampaignForceKind.BASE_DEFENSE,
                                faction,
                                ambientHubDefenseForceName(location, faction),
                                trimmedOrFallback(location.name, "Friendly installation"),
                                "Guard the anchorage perimeter and service approaches"),
                        () -> spawnCampaignShip(ctx, ShipRole.PICKET, faction, stationAnchor[0] + 160.0, stationAnchor[1] - 70.0, "Anchorage Guard"));
            }
            if (installationThreat != null) {
                spawnScriptedInstallationThreatEncounterForce(ctx, st, location, installationThreat, stationAnchor[0], stationAnchor[1]);
            }
            addRegionalAmbientHubTraffic(ctx, st, location, region, routeAnchor, stationAnchor, faction);
            return;
        }
        switch (location.type) {
            case RESOURCE_ZONE -> {
                spawnCampaignAsteroidPocket(ctx, resourceAnchor[0], resourceAnchor[1], 10, 1.35, true);
                spawnCampaignAsteroidPocket(ctx, resourceAnchor[0] + 280.0, resourceAnchor[1] - 120.0, 6, 0.95, false);
                spawnCampaignAsteroidPocket(ctx, resourceAnchor[0] - 320.0, resourceAnchor[1] - 170.0, 5, 0.8, false);
                Faction faction = greenSupportFaction(st);
                withCampaignSpawnContext(st,
                        "ambient_resource_site",
                        campaignForceContext(
                                CampaignForceKind.MINING_GROUP,
                            faction,
                            ambientLocalSiteForceName(location, "Survey Group"),
                            trimmedOrFallback(location.name, "Resource pocket"),
                            "Prospect and secure the local ore pocket for campaign logistics"),
                        () -> {
                            spawnCampaignShip(ctx, ShipRole.MINER, faction, resourceAnchor[0] - 90.0, resourceAnchor[1] + 60.0, "Survey Prospector");
                            spawnCampaignShip(ctx, ShipRole.PICKET, faction, resourceAnchor[0] + 240.0, resourceAnchor[1] - 150.0, "Survey Screen");
                        });
                addRegionalAmbientSiteTraffic(ctx, st, location, region, routeAnchor, resourceAnchor);
            }
            case SALVAGE_FIELD -> {
                spawnCampaignSalvagePocket(ctx, resourceAnchor[0] - 40.0, resourceAnchor[1] + 40.0, 10);
                spawnCampaignSalvagePocket(ctx, resourceAnchor[0] + 260.0, resourceAnchor[1] - 130.0, 6);
                Faction faction = greenSupportFaction(st);
                withCampaignSpawnContext(st,
                        "ambient_salvage_site",
                        campaignForceContext(
                                CampaignForceKind.INSTALLATION_TRAFFIC,
                            faction,
                            ambientLocalSiteForceName(location, "Recovery Group"),
                            trimmedOrFallback(location.name, "Salvage pocket"),
                            "Recover valuable wreckage and hold the local salvage lane"),
                        () -> {
                            spawnCampaignShip(ctx, ShipRole.HAULER, faction, routeAnchor[0] + 80.0, routeAnchor[1] + 110.0, "Recovery Tender");
                            spawnCampaignShip(ctx, ShipRole.PATROL, faction, resourceAnchor[0] + 220.0, resourceAnchor[1] - 120.0, "Recovery Screen");
                        });
                addRegionalAmbientSiteTraffic(ctx, st, location, region, routeAnchor, resourceAnchor);
            }
            case HIDDEN_CACHE -> {
                spawnCampaignSalvagePocket(ctx, resourceAnchor[0] - 10.0, resourceAnchor[1], 4);
                spawnCampaignAsteroidPocket(ctx, resourceAnchor[0] + 170.0, resourceAnchor[1] - 80.0, 3, 0.55, false);
                Faction faction = greenSupportFaction(st);
                withCampaignSpawnContext(st,
                        "ambient_cache_site",
                        campaignForceContext(
                                CampaignForceKind.INSTALLATION_TRAFFIC,
                            faction,
                            ambientLocalSiteForceName(location, "Cache Courier Group"),
                            trimmedOrFallback(location.name, "Hidden cache"),
                            "Protect the dead-drop and move stores through the quiet lane"),
                        () -> {
                            spawnCampaignShip(ctx, ShipRole.HAULER, faction, routeAnchor[0] + 60.0, routeAnchor[1] + 80.0, "Cache Runner");
                            spawnCampaignShip(ctx, ShipRole.PICKET, faction, resourceAnchor[0] + 170.0, resourceAnchor[1] - 120.0, "Cache Guard");
                        });
                addRecoverableWreckSite(st, resourceAnchor[0] + 40.0, resourceAnchor[1] + 100.0,
                        salvageRecoveryRoleForSector(st, DiscoveryKind.CACHE),
                        "Cache Cradle",
                        "A mothballed escort frame is tucked behind the cache ballast.");
                addRegionalAmbientSiteTraffic(ctx, st, location, region, routeAnchor, resourceAnchor);
            }
            case DISTRESS_SIGNAL -> {
                spawnAmbientDistressConvoyBattle(ctx, st, location, routeAnchor, resourceAnchor, arrivalDirection, objectiveDirection);
            }
            case STORY_EVENT -> {
                Faction faction = greenSupportFaction(st);
                withCampaignSpawnContext(st,
                        "ambient_story_site",
                        campaignForceContext(
                                CampaignForceKind.INSTALLATION_TRAFFIC,
                            faction,
                            ambientLocalSiteForceName(location, "Relay Watch"),
                            trimmedOrFallback(location.name, "Relay site"),
                            "Hold the relay pocket and protect signal crews working the anomaly"),
                        () -> {
                            spawnCampaignShip(ctx, ShipRole.STATIC_TURRET, faction, resourceAnchor[0], resourceAnchor[1], "Ghost Relay Node");
                            spawnCampaignShip(ctx, ShipRole.PICKET, faction, resourceAnchor[0] + 190.0, resourceAnchor[1] - 140.0, "Relay Scout");
                            spawnCampaignShip(ctx, ShipRole.HAULER, faction, routeAnchor[0] + 70.0, routeAnchor[1] + 90.0, "Signal Tender");
                            if (st.sector >= 10) {
                                spawnCampaignShip(ctx, ShipRole.FRIGATE, faction, resourceAnchor[0] + 320.0, resourceAnchor[1] + 100.0, "Relay Guard");
                            }
                        });
                spawnCampaignSalvagePocket(ctx, routeAnchor[0] - 120.0, routeAnchor[1] + 60.0, 3);
                addRecoverableWreckSite(st, resourceAnchor[0] + 120.0, resourceAnchor[1] + 90.0,
                        salvageRecoveryRoleForSector(st, DiscoveryKind.DATA_RELAY),
                        "Relay Recovery Spine",
                        "A derelict support hull is slaved to the relay's old service arm.");
                addRegionalAmbientSiteTraffic(ctx, st, location, region, routeAnchor, resourceAnchor);
            }
            default -> {
                spawnCampaignSalvagePocket(ctx, x, y, 5);
                Faction faction = greenSupportFaction(st);
                withCampaignSpawnContext(st,
                        "ambient_local_site",
                        campaignForceContext(
                            CampaignForceKind.LOCAL_FORCE,
                            faction,
                            ambientLocalSiteForceName(location, "Local Patrol"),
                            trimmedOrFallback(location.name, "Local contact"),
                            "Secure the local contact pocket and watch for opportunistic threats"),
                        () -> spawnCampaignShip(ctx, ShipRole.PATROL, faction, resourceAnchor[0] + 170.0, resourceAnchor[1] - 90.0, "Site Patrol"));
                addRegionalAmbientSiteTraffic(ctx, st, location, region, routeAnchor, resourceAnchor);
            }
        }
    }

    private static void clearLocalEncounterMapIdentity(CampaignState st) {
        if (st == null) return;
        st.landmarks.clear();
        st.missionSections.clear();
        st.discoverySites.clear();
        st.recoverableWreckSites.clear();
        st.activeMissionSection = 0;
        st.missionSectionTravelLocked = false;
    }

    private static void addEncounterLandmark(CampaignState st, GameContext ctx, LandmarkType type, String label, String subtitle,
                                             double x, double y, double radius, Color fill, Color edge) {
        addLandmark(st, ctx, type, label, subtitle, x, y, radius, fill, edge);
    }

    private static void populateGalaxySearchEncounterLandmarks(GameContext ctx, CampaignState st, GalaxySearchGroup group, TacticalApproachDirection hostileApproach) {
        if (ctx == null || st == null || group == null || ctx.player == null) return;
        double centerX = ambientEncounterCenterX(ctx, st);
        double centerY = ambientEncounterCenterY(ctx, st);
        CampaignLocation anchor = campaignLocationById(st, group.anchorLocationId);
        boolean anchored = anchor != null && (!anchor.services.isEmpty() || anchor.primaryMission);
        double zoneW = openSpaceFleetClashLaneSpacing(ctx);
        addEncounterLandmark(st, ctx, LandmarkType.CORRIDOR, "Allied Entry Zone", "Player and allied committed ships enter from this left-side zone",
                centerX - zoneW, centerY, 230.0,
                new Color(82, 164, 132, 16), new Color(140, 244, 194, 148));
        addEncounterLandmark(st, ctx, LandmarkType.CORRIDOR, "Neutral Drift Zone", "Open center ground between the two fleets",
                centerX, centerY, 250.0,
                new Color(112, 136, 170, 12), new Color(194, 218, 244, 126));
        addEncounterLandmark(st, ctx, LandmarkType.FRONT, "Hostile Battle Zone", "Enemy formation owns the right-side approach",
                centerX + zoneW, centerY, 250.0,
                new Color(160, 70, 70, 16), new Color(255, 150, 150, 152));
        String interceptLabel = anchored ? trimmedOrFallback(anchor.name, "Anchored Intercept") : "Open-Space Intercept";
        String interceptSubtitle = anchored
                ? "Hostile screen caught near " + anchor.name
                : "Free-space hostile contact without hub infrastructure";
        addEncounterLandmark(st, ctx, LandmarkType.CORRIDOR, interceptLabel, interceptSubtitle,
                centerX, centerY, anchored ? 280.0 : 190.0,
                new Color(116, 156, 206, 16), new Color(196, 226, 255, 156));
        addEncounterLandmark(st, ctx, LandmarkType.FRONT, "Hostile Formation", "Enemy intercept pattern entering from the " + approachDirectionLabel(hostileApproach),
                centerX + zoneW + 260.0, centerY - 60.0, 150.0,
                new Color(150, 72, 72, 14), new Color(255, 156, 156, 152));
        if (!anchored) {
            addEncounterLandmark(st, ctx, LandmarkType.CORRIDOR, "Void Drift", "Open trafficless void with no urban support lattice",
                    centerX - 300.0, centerY + 140.0, 120.0,
                    new Color(92, 122, 158, 10), new Color(170, 202, 236, 120));
        } else {
            addEncounterLandmark(st, ctx, LandmarkType.RING, "Harbor Approach", "Transit edge feeding the anchorage screen",
                    centerX - 280.0, centerY + 120.0, 170.0,
                    new Color(108, 170, 208, 12), new Color(180, 232, 255, 132));
        }
    }

    private static void populateAmbientEncounterLandmarks(GameContext ctx, CampaignState st, CampaignLocation location) {
        if (ctx == null || st == null || location == null) return;
        double centerX = ambientEncounterCenterX(ctx, st);
        double centerY = ambientEncounterCenterY(ctx, st);
        CampaignInstallationThreatCase installationThreat = installationThreatCaseById(st, st.activeInstallationThreatCaseId);
        switch (location.type) {
            case RESOURCE_ZONE -> {
                addEncounterLandmark(st, ctx, LandmarkType.CORRIDOR, location.name, "Sparse ore drift and prospecting lanes",
                        centerX, centerY, 170.0,
                        new Color(124, 170, 126, 14), new Color(200, 240, 198, 146));
                addEncounterLandmark(st, ctx, LandmarkType.FRONT, "Ore Drift", "Broken rock stream instead of fixed urban structure",
                        centerX + 290.0, centerY - 120.0, 110.0,
                        new Color(138, 126, 88, 10), new Color(224, 206, 150, 118));
            }
            case SALVAGE_FIELD -> {
                addEncounterLandmark(st, ctx, LandmarkType.FRONT, location.name, "Wreck clusters and drifting debris fields",
                        centerX, centerY, 180.0,
                        new Color(158, 120, 94, 14), new Color(240, 200, 172, 152));
                addEncounterLandmark(st, ctx, LandmarkType.CORRIDOR, "Wreck Belt", "Scattered hulls and salvage trails across the pocket",
                        centerX - 280.0, centerY + 120.0, 130.0,
                        new Color(144, 116, 88, 12), new Color(226, 192, 158, 124));
            }
            case HIDDEN_CACHE -> {
                addEncounterLandmark(st, ctx, LandmarkType.RELAY, location.name, "Quiet cache shadow tucked behind dead mass",
                        centerX, centerY, 130.0,
                        new Color(118, 152, 186, 12), new Color(210, 228, 255, 136));
                addEncounterLandmark(st, ctx, LandmarkType.CORRIDOR, "Cache Umbra", "Low-signature drift pocket with minimal traffic",
                        centerX + 240.0, centerY - 90.0, 110.0,
                        new Color(98, 132, 168, 10), new Color(184, 214, 244, 114));
            }
            case DISTRESS_SIGNAL -> {
                addEncounterLandmark(st, ctx, LandmarkType.COLONY, location.name, "Survivor contact cluster and emergency maneuvering room",
                        centerX, centerY, 180.0,
                        new Color(148, 166, 196, 16), new Color(224, 236, 255, 154));
                addEncounterLandmark(st, ctx, LandmarkType.CORRIDOR, "Rescue Drift", "Loose civilian drift pattern rather than a fixed city layout",
                        centerX - 260.0, centerY + 140.0, 120.0,
                        new Color(126, 158, 198, 10), new Color(204, 228, 255, 122));
            }
            case STORY_EVENT -> {
                addEncounterLandmark(st, ctx, LandmarkType.RELAY, location.name, "Ghost relay contact with isolated service debris",
                        centerX, centerY, 170.0,
                        new Color(114, 180, 180, 14), new Color(184, 244, 244, 150));
                addEncounterLandmark(st, ctx, LandmarkType.CORRIDOR, "Signal Echo", "Dead channel pocket with almost no local traffic",
                        centerX + 250.0, centerY + 100.0, 110.0,
                        new Color(102, 160, 160, 10), new Color(176, 234, 234, 118));
            }
            case REPAIR_SITE, MAIN_MISSION -> {
                addEncounterLandmark(st, ctx, LandmarkType.COLONY, location.name, "Anchorage traffic, docks, and service spines",
                        centerX, centerY, 250.0,
                        new Color(110, 154, 206, 18), new Color(204, 228, 255, 168));
                addEncounterLandmark(st, ctx, LandmarkType.RING, "Service Halo", "Docking ring, tenders, and local harbor corridors",
                        centerX + 260.0, centerY - 100.0, 180.0,
                        new Color(116, 186, 214, 12), new Color(182, 240, 255, 132));
                if (installationThreat != null) {
                    addEncounterLandmark(st, ctx, LandmarkType.FRONT, "Hostile Ingress", installationThreat.forceName + " breaking into the installation perimeter",
                            centerX + missionLayout(ctx).subzoneWidth, centerY - 40.0, 170.0,
                            new Color(168, 76, 76, 16), new Color(255, 158, 158, 154));
                }
            }
            default -> {
                if (!location.services.isEmpty()) {
                    addEncounterLandmark(st, ctx, LandmarkType.COLONY, location.name, "Anchorage-scale local traffic and service routes",
                            centerX, centerY, 230.0,
                            new Color(110, 154, 206, 18), new Color(204, 228, 255, 168));
                } else {
                    addEncounterLandmark(st, ctx, LandmarkType.CORRIDOR, location.name, "Small local contact pocket with limited surrounding structure",
                            centerX, centerY, 150.0,
                            new Color(110, 140, 178, 12), new Color(194, 216, 244, 128));
                }
            }
        }
    }

    private static void addRegionalAmbientHubTraffic(GameContext ctx, CampaignState st, CampaignLocation location,
                                                     GalaxyRegionIdentity region, double[] routeAnchor,
                                                     double[] stationAnchor, Faction faction) {
        if (ctx == null || st == null || location == null || faction == null || region == null) return;
        double routeX = (routeAnchor == null || routeAnchor.length < 2) ? ambientEncounterCenterX(ctx, st) - 220.0 : routeAnchor[0];
        double routeY = (routeAnchor == null || routeAnchor.length < 2) ? ambientEncounterCenterY(ctx, st) : routeAnchor[1];
        double stationX = (stationAnchor == null || stationAnchor.length < 2) ? ambientEncounterCenterX(ctx, st) + 220.0 : stationAnchor[0];
        double stationY = (stationAnchor == null || stationAnchor.length < 2) ? ambientEncounterCenterY(ctx, st) : stationAnchor[1];
        withCampaignSpawnContext(st,
                "ambient_hub_regional",
                campaignForceContext(
                        ambientRegionalHubForceKind(location, region, faction),
                        faction,
                        ambientRegionalHubForceName(location, region, faction),
                        trimmedOrFallback(location.name, "Friendly installation"),
                        "Regional traffic and local escort force tied to the installation's surrounding lanes"),
                () -> {
                    switch (region) {
                        case SOUTHERN_SHELTER -> {
                            spawnCampaignShip(ctx, ShipRole.HAULER, faction, routeX + 70.0, routeY - 40.0, "Shelter Route Tender");
                            spawnCampaignShip(ctx, ShipRole.CIWS_CORVETTE, faction, stationX + 90.0, stationY + 170.0, "Shelter Flak Boat");
                        }
                        case CONTESTED_BELT -> {
                            spawnCampaignShip(ctx, ShipRole.PATROL, faction, routeX + 110.0, routeY + 20.0, "Raid Belt Cutter");
                            spawnCampaignShip(ctx, ShipRole.HAULER, faction, stationX + 60.0, stationY - 170.0, "Broker Drift Tender");
                        }
                        case EARTHWARDED_NORTH -> {
                            spawnCampaignShip(ctx, ShipRole.FRIGATE, faction, stationX - 120.0, stationY + 90.0, "Blackout Guard");
                            spawnCampaignShip(ctx, ShipRole.PICKET, faction, routeX + 150.0, routeY - 170.0, "Resistance Wake Screen");
                        }
                    }
                });
    }

    private static void spawnScriptedInstallationThreatEncounterForce(GameContext ctx,
                                                                      CampaignState st,
                                                                      CampaignLocation location,
                                                                      CampaignInstallationThreatCase threat,
                                                                      double stationX,
                                                                      double stationY) {
        if (ctx == null || st == null || location == null || threat == null) return;
        TacticalApproachDirection ingressDirection = deriveApproachDirection(stationX + 320.0, stationY, stationX, stationY);
        double[] ingress = ambientApproachPoint(ctx, st, ingressDirection, 0.64);
        withCampaignSpawnContext(st,
                "scripted_installation_threat",
                campaignForceContext(
                        CampaignForceKind.STRIKE_DETACHMENT,
                        Faction.ENEMY,
                        threat.forceName,
                        threat.origin,
                        threat.warning),
                () -> {
                    spawnEnemyAtPoint(ctx, ShipRole.PATROL, ingress[0] - 90.0, ingress[1] + 70.0);
                    spawnEnemyAtPoint(ctx, ShipRole.PICKET, ingress[0] + 60.0, ingress[1] - 110.0);
                    if (threat.threatLevel >= 0.30) {
                        spawnEnemyAtPoint(ctx, ShipRole.FRIGATE, ingress[0] + 150.0, ingress[1] + 20.0);
                    }
                    if (threat.threatLevel >= 0.55) {
                        spawnEnemyAtPoint(ctx, ShipRole.MISSILE_BOAT, ingress[0] + 260.0, ingress[1] - 70.0);
                    }
                });
    }

    private static void addRegionalAmbientSiteTraffic(GameContext ctx, CampaignState st, CampaignLocation location,
                                                      GalaxyRegionIdentity region, double[] routeAnchor, double[] objectiveAnchor) {
        if (ctx == null || st == null || location == null || region == null) return;
        Faction green = greenSupportFaction(st);
        Faction yellow = yellowSupportFaction(st);
        double routeX = (routeAnchor == null || routeAnchor.length < 2) ? ambientEncounterCenterX(ctx, st) - 220.0 : routeAnchor[0];
        double routeY = (routeAnchor == null || routeAnchor.length < 2) ? ambientEncounterCenterY(ctx, st) : routeAnchor[1];
        double objectiveX = (objectiveAnchor == null || objectiveAnchor.length < 2) ? ambientEncounterCenterX(ctx, st) + 220.0 : objectiveAnchor[0];
        double objectiveY = (objectiveAnchor == null || objectiveAnchor.length < 2) ? ambientEncounterCenterY(ctx, st) : objectiveAnchor[1];
        withCampaignSpawnContext(st,
                "ambient_site_regional",
                campaignForceContext(
                        ambientRegionalSiteForceKind(location, region),
                        ambientRegionalSiteForceFaction(location, region, green, yellow),
                        ambientRegionalSiteForceName(location, region),
                        trimmedOrFallback(location.name, "Regional site"),
                        "Regional support, recovery, mining, or escort force tied to this local contact"),
                () -> {
                    switch (location.type) {
                        case RESOURCE_ZONE -> {
                            switch (region) {
                                case SOUTHERN_SHELTER -> {
                                    spawnCampaignShip(ctx, ShipRole.HAULER, green, objectiveX + 90.0, objectiveY + 170.0, "Shelter Ore Tender");
                                    spawnCampaignShip(ctx, ShipRole.MINER, green, objectiveX - 260.0, objectiveY - 40.0, "Lane Prospector");
                                }
                                case CONTESTED_BELT -> {
                                    spawnCampaignShip(ctx, ShipRole.PATROL, green, objectiveX + 80.0, objectiveY - 180.0, "Raid Screen");
                                    spawnCampaignSalvagePocket(ctx, objectiveX + 40.0, objectiveY + 180.0, 3);
                                }
                                case EARTHWARDED_NORTH -> {
                                    spawnCampaignShip(ctx, ShipRole.FRIGATE, green, objectiveX + 80.0, objectiveY - 180.0, "Resistance Fuel Guard");
                                    spawnCampaignShip(ctx, ShipRole.PICKET, green, objectiveX - 300.0, objectiveY + 30.0, "Cold Belt Screen");
                                }
                            }
                        }
                        case SALVAGE_FIELD -> {
                            switch (region) {
                                case SOUTHERN_SHELTER -> spawnCampaignShip(ctx, ShipRole.TRANSPORT, green, routeX + 170.0, routeY + 150.0, "Shelter Recovery Barge");
                                case CONTESTED_BELT -> {
                                    spawnCampaignShip(ctx, ShipRole.PICKET, green, routeX + 80.0, routeY - 120.0, "Raid Wake Escort");
                                    spawnCampaignSalvagePocket(ctx, objectiveX + 220.0, objectiveY + 70.0, 4);
                                }
                                case EARTHWARDED_NORTH -> {
                                    spawnCampaignShip(ctx, ShipRole.FRIGATE, green, objectiveX + 70.0, objectiveY - 150.0, "Burnline Guard");
                                    spawnCampaignShip(ctx, ShipRole.CIWS_CORVETTE, green, routeX + 110.0, routeY + 130.0, "Intercept Wreck Screen");
                                }
                            }
                        }
                        case HIDDEN_CACHE -> {
                            switch (region) {
                                case SOUTHERN_SHELTER -> spawnCampaignShip(ctx, ShipRole.TRANSPORT, green, routeX - 10.0, routeY - 70.0, "Shelter Cache Skiff");
                                case CONTESTED_BELT -> spawnCampaignShip(ctx, ShipRole.PATROL, green, objectiveX + 220.0, objectiveY + 100.0, "False-Lane Decoy");
                                case EARTHWARDED_NORTH -> spawnCampaignShip(ctx, ShipRole.FRIGATE, green, routeX + 40.0, routeY - 50.0, "Resistance Dead-Drop Guard");
                            }
                        }
                        case DISTRESS_SIGNAL -> {
                            switch (region) {
                                case SOUTHERN_SHELTER -> spawnCampaignShip(ctx, ShipRole.HAULER, yellow, routeX - 70.0, routeY - 80.0, "Shelter Relief Tender");
                                case CONTESTED_BELT -> spawnCampaignShip(ctx, ShipRole.PATROL, yellow, routeX - 30.0, routeY + 110.0, "Runner Rescue Screen");
                                case EARTHWARDED_NORTH -> {
                                    spawnCampaignShip(ctx, ShipRole.FRIGATE, yellow, routeX - 40.0, routeY + 100.0, "Resistance Lift Escort");
                                    spawnCampaignShip(ctx, ShipRole.CIWS_CORVETTE, yellow, routeX + 220.0, routeY + 170.0, "Hunt-Lane Screen");
                                }
                            }
                        }
                        case STORY_EVENT -> {
                            switch (region) {
                                case SOUTHERN_SHELTER -> spawnCampaignShip(ctx, ShipRole.HAULER, green, routeX - 30.0, routeY - 40.0, "Relay Choir Tender");
                                case CONTESTED_BELT -> spawnCampaignShip(ctx, ShipRole.PATROL, green, objectiveX + 200.0, objectiveY + 90.0, "Ghost Courier");
                                case EARTHWARDED_NORTH -> {
                                    spawnCampaignShip(ctx, ShipRole.FRIGATE, green, routeX - 20.0, routeY + 70.0, "Black Relay Guard");
                                    spawnCampaignShip(ctx, ShipRole.CIWS_CORVETTE, green, objectiveX + 100.0, objectiveY + 170.0, "Uplink Screen");
                                }
                            }
                        }
                        case REPAIR_SITE -> {
                            if (region == GalaxyRegionIdentity.EARTHWARDED_NORTH) {
                                spawnCampaignShip(ctx, ShipRole.PATROL, green, routeX - 10.0, routeY - 70.0, "Hard-Dock Escort");
                            }
                        }
                        default -> {
                        }
                    }
                });
    }

    private static String ambientHubDefenseForceName(CampaignLocation location, Faction faction) {
        String site = trimmedOrFallback(location == null ? null : location.name, "Local Hub");
        return site + " Defense Force";
    }

    private static String ambientHubTrafficForceName(CampaignLocation location, Faction faction) {
        String site = trimmedOrFallback(location == null ? null : location.name, "Local Hub");
        if (location != null && isYellowAlignedLocation(location)) return site + " Trade Traffic Group";
        return site + " Service Traffic Group";
    }

    private static String ambientHubMiningForceName(CampaignLocation location, Faction faction) {
        String site = trimmedOrFallback(location == null ? null : location.name, "Local Hub");
        return site + " Prospecting Group";
    }

    private static String ambientLocalSiteForceName(CampaignLocation location, String suffix) {
        String site = trimmedOrFallback(location == null ? null : location.name, "Local Site");
        String tail = (suffix == null || suffix.isBlank()) ? "Local Force" : suffix.trim();
        return site + " " + tail;
    }

    private static CampaignForceKind ambientRegionalHubForceKind(CampaignLocation location, GalaxyRegionIdentity region, Faction faction) {
        if (region == GalaxyRegionIdentity.SOUTHERN_SHELTER && faction != null && faction == Faction.TEAM_D) return CampaignForceKind.TRADE_GROUP;
        if (region == GalaxyRegionIdentity.CONTESTED_BELT) return CampaignForceKind.INSTALLATION_TRAFFIC;
        return CampaignForceKind.BASE_DEFENSE;
    }

    private static String ambientRegionalHubForceName(CampaignLocation location, GalaxyRegionIdentity region, Faction faction) {
        String site = trimmedOrFallback(location == null ? null : location.name, "Local Hub");
        return switch (region) {
            case SOUTHERN_SHELTER -> site + " Shelter Routes Group";
            case CONTESTED_BELT -> site + " Belt Traffic Group";
            case EARTHWARDED_NORTH -> site + " Wake Guard";
        };
    }

    private static CampaignForceKind ambientRegionalSiteForceKind(CampaignLocation location, GalaxyRegionIdentity region) {
        if (location == null) return CampaignForceKind.LOCAL_FORCE;
        return switch (location.type) {
            case RESOURCE_ZONE -> CampaignForceKind.MINING_GROUP;
            case SALVAGE_FIELD, HIDDEN_CACHE, STORY_EVENT, REPAIR_SITE -> CampaignForceKind.INSTALLATION_TRAFFIC;
            case DISTRESS_SIGNAL -> CampaignForceKind.CONVOY;
            default -> CampaignForceKind.LOCAL_FORCE;
        };
    }

    private static Faction ambientRegionalSiteForceFaction(CampaignLocation location, GalaxyRegionIdentity region, Faction green, Faction yellow) {
        return location != null && location.type == CampaignLocationType.DISTRESS_SIGNAL ? yellow : green;
    }

    private static String ambientRegionalSiteForceName(CampaignLocation location, GalaxyRegionIdentity region) {
        String site = trimmedOrFallback(location == null ? null : location.name, "Regional Site");
        return switch (ambientRegionalSiteForceKind(location, region)) {
            case MINING_GROUP -> site + " Extraction Group";
            case CONVOY -> site + " Relief Convoy";
            case INSTALLATION_TRAFFIC -> site + " Service Detachment";
            default -> site + " Local Detail";
        };
    }

    private static void positionPlayerForAmbientEncounter(GameContext ctx, CampaignState st, CampaignLocation location) {
        if (ctx == null || st == null || ctx.player == null) return;
        int ambientSubzone = missionSubzoneIndex(Math.max(0, missionSubzoneColumns() / 2), Math.max(0, missionSubzoneRows() / 2));
        double centerX = missionSubzoneCenterX(ctx, st.sector, ambientSubzone);
        double centerY = missionSubzoneCenterY(ctx, st.sector, ambientSubzone);
        TacticalApproachDirection arrivalDirection = ambientEncounterArrivalDirection(st, location);
        double[] arrival = ambientApproachPoint(ctx, st, arrivalDirection, 0.72);
        setLoadedMissionSubzone(ctx, ambientSubzone);
        st.galaxyAmbientPocketCenterX = centerX;
        st.galaxyAmbientPocketCenterY = centerY;
        double radiusCap = Math.min(AMBIENT_SITE_POCKET_RADIUS,
                Math.min(AMBIENT_SITE_POCKET_WIDTH * 0.5, AMBIENT_SITE_POCKET_HEIGHT * 0.5));
        st.galaxyAmbientPocketRadius = Math.max(1200.0, radiusCap);
        ctx.player.x = arrival[0];
        ctx.player.y = arrival[1];
        ctx.player.angle = pointAngleToward(ctx.player.x, ctx.player.y, centerX, centerY);
        ctx.player.campaignMissionSubzone = ambientSubzone;
        ctx.camX = ctx.player.x;
        ctx.camY = ctx.player.y;
    }

    private static double ambientEncounterCenterX(GameContext ctx, CampaignState st) {
        if (st != null && Double.isFinite(st.galaxyAmbientPocketCenterX)) return st.galaxyAmbientPocketCenterX;
        return (ctx == null) ? 0.0 : ctx.WORLD_W * 0.5;
    }

    private static double ambientEncounterCenterY(GameContext ctx, CampaignState st) {
        if (st != null && Double.isFinite(st.galaxyAmbientPocketCenterY)) return st.galaxyAmbientPocketCenterY;
        return (ctx == null) ? 0.0 : ctx.WORLD_H * 0.5;
    }

    private static double ambientEncounterRadius(CampaignState st) {
        return (st == null) ? AMBIENT_SITE_POCKET_RADIUS : Math.max(900.0,
                Double.isFinite(st.galaxyAmbientPocketRadius) ? st.galaxyAmbientPocketRadius : AMBIENT_SITE_POCKET_RADIUS);
    }

    private static Faction ambientLocationFaction(CampaignState st, CampaignLocation location) {
        if (location == null) return greenSupportFaction(st);
        if (isYellowAlignedLocation(location)) return yellowSupportFaction(st);
        if (isGreenAlignedLocation(location)) return greenSupportFaction(st);
        return greenSupportFaction(st);
    }

    private static Faction recurringContactMarkerFaction(String recurringContactId) {
        String id = (recurringContactId == null) ? "" : recurringContactId.trim().toUpperCase(Locale.US);
        return switch (id) {
            case "VOSS" -> Faction.TEAM_C;
            case "MARR" -> Faction.TEAM_D;
            case "ROOK" -> Faction.ENEMY;
            default -> null;
        };
    }

    private static Faction locationDisplayMarkerFaction(CampaignLocation location) {
        if (location == null) return null;
        Faction recurringFaction = recurringContactMarkerFaction(location.recurringContactId);
        if (recurringFaction != null) return recurringFaction;
        if (location.type == CampaignLocationType.ENEMY_ACTIVITY) return Faction.ENEMY;
        if (isYellowAlignedLocation(location)) return Faction.TEAM_D;
        if (isGreenAlignedLocation(location)) return Faction.TEAM_C;
        return null;
    }

    private static boolean isGreenAlignedLocation(CampaignLocation location) {
        if (location == null) return false;
        String name = (location.name == null) ? "" : location.name.toUpperCase(Locale.US);
        String detail = (location.detail == null) ? "" : location.detail.toUpperCase(Locale.US);
        return name.contains("GREEN") || detail.contains("GREEN") || detail.contains("COALITION") || detail.contains("RESISTANCE");
    }

    private static boolean isYellowAlignedLocation(CampaignLocation location) {
        if (location == null) return false;
        String name = (location.name == null) ? "" : location.name.toUpperCase(Locale.US);
        String detail = (location.detail == null) ? "" : location.detail.toUpperCase(Locale.US);
        return name.contains("YELLOW") || detail.contains("YELLOW") || detail.contains("BROKER") || detail.contains("MARKET");
    }

    private static int spawnGalaxySearchGroupEncounterForce(GameContext ctx, CampaignState st, GalaxySearchGroup group, TacticalApproachDirection hostileApproach) {
        if (ctx == null || st == null || group == null || ctx.player == null) return 0;
        int hostileZone = missionSubzoneIndex(2, 1);
        double[] ingress = openSpaceFleetClashApproachPoint(ctx, st, 1, hostileApproach, 150.0);
        CampaignLocation anchor = campaignLocationById(st, group.anchorLocationId);
        String hostileForceName = hostileSearchGroupDisplayName(st, group);
        String hostileOrigin = (anchor != null)
                ? trimmedOrFallback(anchor.name, "Hostile anchor")
                : "Overmap search group at X " + (int) Math.round(group.x) + " Y " + (int) Math.round(group.y);
        String hostilePurpose = (anchor != null && anchor.type == CampaignLocationType.ENEMY_ACTIVITY)
                ? "Hold the hostile point of interest and intercept nearby fleets"
                : "Intercepting the player fleet from a visible strategic contact";
        CampaignForce owner = campaignForceForLinkedSearchGroup(st, group);
        if (owner == null) {
            owner = ensureCampaignForce(st,
                    anchor != null && anchor.type == CampaignLocationType.ENEMY_ACTIVITY
                            ? CampaignForceKind.BASE_DEFENSE
                            : CampaignForceKind.PATROL_GROUP,
                    Faction.ENEMY,
                    hostileForceName,
                    hostileOrigin,
                    hostilePurpose,
                    group.x,
                    group.y);
        }
        EncounterForceManifest manifest = encounterManifestForForce(ctx, st, owner, Math.max(1, 2 + group.tier));
        int spawned = spawnNamedEncounterManifest(ctx, st,
                "galaxy_search_group_encounter",
                owner,
                manifest,
                ingress[0],
                ingress[1],
                130.0,
                100.0,
                true);
        for (Ship ship : ctx.ships) {
            if (ship != null && ship.faction == Faction.ENEMY && st.shipCampaignForceIds.getOrDefault(ship.id, 0) == owner.id) {
                ship.campaignMissionSubzone = hostileZone;
                st.authoredObjectiveHostiles.add(ship.id);
            }
        }
        if (anchor != null) {
            spawned += spawnNearbyPoiParticipants(ctx, st, anchor, owner, hostileApproach);
        }
        return spawned;
    }

    private static String overmapHudDetail(GameContext ctx, CampaignState st, boolean expanded) {
        if (ctx == null || st == null) return "";
        ArrayList<String> lines = new ArrayList<>();
        CampaignLocation current = currentCampaignLocation(ctx);
        CampaignLocation selected = selectedCampaignLocation(ctx);
        CampaignTravelState travel = st.galaxyTravel;
        SectorLore lore = loreFor(st.sector);
        SectorScript script = scriptFor(st.sector);
        addObjectiveLine(lines, "Episode: " + actTitleFor(st.act) + " / " + lore.title);
        addObjectiveLine(lines, "AO: " + lore.location);
        addObjectiveLine(lines, lore.hudLead);
        if (script != null) addObjectiveLine(lines, "Tactical Brief: " + script.objectiveLabel);
        addObjectiveLine(lines, "Mode: Strategic galaxy map only; ships and combat exist only inside encounters");
        addObjectiveLine(lines, "Main Missions: " + st.completedMainMissions + " / 24 complete");
        addObjectiveLine(lines, "Earth Progress: " + (int) Math.round(st.earthProgress * 100.0) + "%");
        addObjectiveLine(lines, "Current Location: " + ((current == null) ? "Unknown" : current.name));
        if (selected != null) {
            addObjectiveLine(lines, "Selected Destination: " + selected.name);
            addObjectiveLine(lines, "Threat Estimate: " + threatReadout(selected.threatLevel));
            for (String routeLine : selectedRouteAssessmentLines(ctx)) {
                addObjectiveLine(lines, routeLine);
            }
        }
        if (travel.traveling) {
            CampaignLocation destination = campaignLocationById(st, travel.destinationId);
            int eta = (int) Math.ceil(Math.max(0.0, (1.0 - travel.progress) * travel.durationSec));
            addObjectiveLine(lines, "Travel State: En route to " + ((destination == null) ? "destination" : destination.name) + "  ETA " + eta + "s");
            addObjectiveLine(lines, "Interception Risk: " + (int) Math.round(travel.interceptionRisk) + "%");
        } else {
            addObjectiveLine(lines, "Travel State: Idle and ready to depart");
        }
        addObjectiveLine(lines, "Enemy Alert: " + threatReadout((float) MathUtil.clamp(st.enemyAlertLevel / 100.0, 0.0, 1.0)));
        addObjectiveLine(lines, "Intel Quality: " + campaignIntelReadout(ctx));
        addObjectiveLine(lines, "Operational Exposure: " + campaignExposureReadout(ctx));
        addObjectiveLine(lines, "Regional Danger: " + regionalPressureLabel(regionPressureAt(ctx, st.playerGalaxyX, st.playerGalaxyY)));
        if (expanded) {
            addObjectiveLine(lines, "Controls: arrows pan camera north-south  |  LMB select destination  |  Double-click or T to travel  |  RMB ping");
            addObjectiveLine(lines, "Map Rule: This is a large strategic chart; only part of the route home is visible at once.");
            addObjectiveLine(lines, "Progression: Southern frontier below, contested mid-map ahead, Earth approach far to the north.");
            addObjectiveLine(lines, "Encounter Rule: Bases, hubs, and risky routes transition into one large tactical sector.");
        } else {
            addObjectiveLine(lines, "Task: Move north toward Earth, weigh safe hubs against risky detours, and plan the next stop.");
        }
        return String.join("\n", lines);
    }

    public static int livePersistentFleetCount(GameContext ctx) {
        CampaignState st = state(ctx);
        return livePersistentFleetSlots(st);
    }

    static int livePersistentFleetCount(GameContext ctx, ShopHullCategory category) {
        return livePersistentFleetSlots(state(ctx), category);
    }

    static int persistentFleetBaseCap(ShopHullCategory category) {
        ShopHullCategory resolved = (category == null) ? ShopHullCategory.ESCORT : category;
        return switch (resolved) {
            case ESCORT -> CAMPAIGN_BLUE_ESCORT_CAP;
            case LINE -> CAMPAIGN_BLUE_LINE_CAP;
            case CAPITAL -> CAMPAIGN_BLUE_CAPITAL_CAP;
            case TITAN -> TitanFleetSystem.mothershipTitanCap();
        };
    }

    static int persistentFleetCap(ShopHullCategory category) {
        return persistentFleetBaseCap(category);
    }

    static int persistentFleetCap(GameContext ctx, ShopHullCategory category) {
        return persistentFleetCap(state(ctx), category);
    }

    static int persistentFleetCap(CampaignState st, ShopHullCategory category) {
        return persistentFleetBaseCap(category);
    }

    static String persistentFleetCompactSummary(GameContext ctx) {
        int escort = livePersistentFleetCount(ctx, ShopHullCategory.ESCORT);
        int line = livePersistentFleetCount(ctx, ShopHullCategory.LINE);
        int capital = livePersistentFleetCount(ctx, ShopHullCategory.CAPITAL);
        int titan = livePersistentFleetCount(ctx, ShopHullCategory.TITAN);
        return "E" + escort
                + " L" + line
                + " C" + capital
                + " T" + titan + "/" + persistentFleetCap(ctx, ShopHullCategory.TITAN);
    }

    private static int standardCommandCapacity(CampaignState st) {
        int capacity = CAMPAIGN_FLAGSHIP_STANDARD_COMMAND_CAPACITY;
        if (st == null) return capacity;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            TitanArchetype titan = (entry == null || entry.destroyed) ? null : TitanArchetype.fromShipRole(entry.role);
            if (titan == null) continue;
            capacity += titan.standardShipCommandCapacity();
        }
        return Math.max(0, capacity);
    }

    private static int standardCommandUsed(CampaignState st) {
        if (st == null) return 0;
        int used = 0;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            used += campaignStandardCommandCost(entry.role);
        }
        return Math.max(0, used);
    }

    private static int eliteCommandCapacity(GameContext ctx, CampaignState st) {
        if (st == null) return 0;
        int capacity = flagshipEliteCommandCapacity(ctx, st);
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            TitanArchetype titan = (entry == null || entry.destroyed) ? null : TitanArchetype.fromShipRole(entry.role);
            if (titan == null) continue;
            capacity += titan.eliteSupershipCommandCapacity();
        }
        return Math.max(0, capacity);
    }

    private static int flagshipEliteCommandCapacity(GameContext ctx, CampaignState st) {
        if (ctx == null || st == null || !st.enabled || ctx.player == null) return 0;
        if (st.sector < CAMPAIGN_SUPERSHIP_UNLOCK_SECTOR) return 0;
        BaseUpgrades upgrades = ctx.baseUpgrades.get(ctx.player);
        int hangarTier = (upgrades == null) ? 0 : upgrades.hangarLv;
        if (hangarTier < CAMPAIGN_SUPERSHIP_FLAGSHIP_BERTH_TIER) return 0;
        return CAMPAIGN_FLAGSHIP_BUILTIN_ELITE_COMMAND_CAPACITY;
    }

    private static int eliteCommandUsed(CampaignState st) {
        if (st == null) return 0;
        int used = 0;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            used += campaignEliteCommandCost(entry.role);
        }
        return Math.max(0, used);
    }

    private static boolean hasOperationalRole(CampaignState st, ShipRole role) {
        if (st == null || role == null) return false;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            if (entry.role == role) return true;
        }
        return false;
    }

    public static String[] activeModifierLabels(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null || !st.enabled || st.activeModifiers == null) return new String[0];
        String[] out = new String[st.activeModifiers.length];
        int n = 0;
        for (MapModifier m : st.activeModifiers) {
            if (m == null || m == MapModifier.NONE) continue;
            out[n++] = m.label;
        }
        if (n == out.length) return out;
        String[] trim = new String[n];
        System.arraycopy(out, 0, trim, 0, n);
        return trim;
    }

    public static Color worldTint(GameContext ctx) {
        CampaignState st = state(ctx);
        if (st == null || !st.enabled || st.activeModifiers == null) return new Color(0, 0, 0, 0);
        int r = 0, g = 0, b = 0, a = 0;
        for (MapModifier m : st.activeModifiers) {
            Color t = tintFor(m);
            if (t == null) continue;
            r += t.getRed();
            g += t.getGreen();
            b += t.getBlue();
            a += t.getAlpha();
        }
        if (a <= 0) return new Color(0, 0, 0, 0);
        int n = Math.max(1, st.activeModifiers.length);
        return new Color(
                MathUtil.clamp(r / n, 0, 255),
                MathUtil.clamp(g / n, 0, 255),
                MathUtil.clamp(b / n, 0, 255),
                MathUtil.clamp(a / n, 0, 90)
        );
    }

    private static CampaignState state(GameContext ctx) {
        if (ctx == null) return null;
        return ctx.campaign;
    }

    private static List<CampaignLocation> allCampaignLocations(CampaignState st) {
        if (st == null) return List.of();
        ArrayList<CampaignLocation> out = new ArrayList<>(st.galaxyMainPois.size() + st.galaxyAreasOfInterest.size());
        out.addAll(st.galaxyMainPois);
        out.addAll(st.galaxyAreasOfInterest);
        return out;
    }

    private static CampaignLocation campaignLocationById(CampaignState st, String id) {
        if (st == null || id == null || id.isBlank()) return null;
        for (CampaignLocation location : allCampaignLocations(st)) {
            if (location != null && id.equalsIgnoreCase(location.id)) return location;
        }
        return null;
    }

    private static void initializeStrategicTaskForces(GameContext ctx, CampaignState st) {
        if (ctx == null || st == null) return;
        st.strategicTaskForces.clear();
        st.strategicDivisions.clear();
        st.strategicTorpedoCharges = STARTING_TORPEDO_INVENTORY;
        st.strategicSortiesLaunched = 0;
        st.strategicAtomicCharges = STARTING_ATOMIC_INVENTORY;
        int playerSubzone = currentLoadedMissionSubzone(ctx);
        if (playerSubzone < 0) playerSubzone = missionSubzoneIndex(0, 1);
        initializeStrategicDivisions(ctx, st, playerSubzone);

        int patrolSubzone = farthestSubzoneFrom(playerSubzone, Set.of());
        int strikeSubzone = farthestSubzoneFrom(playerSubzone, Set.of(patrolSubzone));
        int stealthSubzone = flankSubzone(playerSubzone, Set.of(patrolSubzone, strikeSubzone));
        int convoySubzone = supportSubzoneNear(playerSubzone, Set.of(patrolSubzone, strikeSubzone, stealthSubzone), true);
        int salvageSubzone = supportSubzoneNear(playerSubzone, Set.of(patrolSubzone, strikeSubzone, stealthSubzone, convoySubzone), false);

        addStrategicTaskForce(st, StrategicTaskForceKind.PATROL, Faction.ENEMY,
                "Red Patrol Group", true, true, SupportMarkerType.HAZARD, patrolSubzone, 8.0);
        addStrategicTaskForce(st, StrategicTaskForceKind.STRIKE, Faction.ENEMY,
                "Red Strike Group", true, true, SupportMarkerType.HAZARD, strikeSubzone, 12.0);
        addStrategicTaskForce(st, StrategicTaskForceKind.PATROL, Faction.ENEMY,
                "Red Route Hunters", true, true, SupportMarkerType.HAZARD,
                supportSubzoneNear(playerSubzone, Set.of(strikeSubzone), false), 7.0);
        if (st.sector >= 4) {
            addStrategicTaskForce(st, StrategicTaskForceKind.CONVOY, greenSupportFaction(st),
                    "Coalition Supply Convoy", false, false, SupportMarkerType.RESOURCE, convoySubzone, 14.0);
        }
        if (st.sector >= 6) {
            addStrategicTaskForce(st, StrategicTaskForceKind.STEALTH, Faction.ENEMY,
                    "Knife Raider Cell", true, true, SupportMarkerType.HAZARD, stealthSubzone, 10.0);
        }
        if (st.sector >= 3) {
            addStrategicTaskForce(st, StrategicTaskForceKind.SALVAGE, greenSupportFaction(st),
                    "Recovery Flotilla", false, false, SupportMarkerType.SALVAGE, salvageSubzone, 16.0);
        }
        for (StrategicTaskForce taskForce : st.strategicTaskForces) {
            if (taskForce == null) continue;
            taskForce.maxStrength = rawStrategicTaskForceThreat(taskForce.kind, st.sector);
            taskForce.currentStrength = taskForce.maxStrength;
        }
    }

    private static StrategicTaskForce addStrategicTaskForce(CampaignState st,
                                                            StrategicTaskForceKind kind,
                                                            Faction faction,
                                                            String label,
                                                            boolean hostile,
                                                            boolean spawnsEncounter,
                                                            SupportMarkerType markerType,
                                                            int subzone,
                                                            double dwellSeconds) {
        if (st == null || subzone < 0) return null;
        StrategicTaskForce taskForce = new StrategicTaskForce(
                st.nextStrategicTaskForceId++,
                kind,
                faction,
                label,
                hostile,
                spawnsEncounter,
                markerType,
                subzone,
                dwellSeconds);
        st.strategicTaskForces.add(taskForce);
        return taskForce;
    }

    private static void initializeSearchGroupSensorProfile(GalaxySearchGroup group) {
        if (group == null) return;
        double threat = MathUtil.clamp(group.threatLevel, 0.0, 1.0);
        double tier = MathUtil.clamp(group.tier / 4.0, 0.0, 1.0);
        switch ((group.doctrine == null) ? GalaxySearchDoctrine.SCOUT_SCREEN : group.doctrine) {
            case SCOUT_SCREEN -> {
                group.engineSignature = 0.34 + threat * 0.14;
                group.commsSignature = 0.42 + tier * 0.16;
                group.massSignature = 0.28 + tier * 0.12;
                group.heatSignature = 0.22 + threat * 0.10;
                group.decoyRisk = 0.20 + threat * 0.12;
            }
            case HUNTER_KILLER -> {
                group.engineSignature = 0.58 + threat * 0.18;
                group.commsSignature = 0.30 + tier * 0.10;
                group.massSignature = 0.52 + threat * 0.16;
                group.heatSignature = 0.62 + tier * 0.14;
                group.decoyRisk = 0.10 + threat * 0.08;
            }
            case BLOCKADE_GROUP -> {
                group.engineSignature = 0.26 + tier * 0.08;
                group.commsSignature = 0.56 + threat * 0.16;
                group.massSignature = 0.68 + tier * 0.18;
                group.heatSignature = 0.38 + threat * 0.12;
                group.decoyRisk = 0.42 + threat * 0.18;
            }
            case INTERDICTION_GROUP -> {
                group.engineSignature = 0.46 + threat * 0.14;
                group.commsSignature = 0.40 + tier * 0.14;
                group.massSignature = 0.44 + threat * 0.12;
                group.heatSignature = 0.36 + tier * 0.12;
                group.decoyRisk = 0.30 + threat * 0.14;
            }
            case PUNISHMENT_FLEET -> {
                group.engineSignature = 0.72 + threat * 0.16;
                group.commsSignature = 0.48 + tier * 0.12;
                group.massSignature = 0.76 + threat * 0.16;
                group.heatSignature = 0.78 + tier * 0.14;
                group.decoyRisk = 0.08 + threat * 0.06;
            }
        }
        group.trackIntegrity = Math.max(group.trackIntegrity, 18.0 + threat * 20.0 + tier * 14.0);
    }

    private static void updateStrategicTaskForces(GameContext ctx, CampaignState st, double dt) {
        if (ctx == null || st == null || st.strategicTaskForces.isEmpty() || dt <= 0.0) return;
        int playerSubzone = currentLoadedMissionSubzone(ctx);
        if (playerSubzone < 0 && ctx.player != null) {
            playerSubzone = missionSubzoneForPoint(ctx, st.sector, ctx.player.x, ctx.player.y);
        }
        updateStrategicDivisions(ctx, st, playerSubzone, dt);
        for (StrategicTaskForce taskForce : st.strategicTaskForces) {
            if (taskForce == null || taskForce.encounterResolved) continue;
            updateStrategicTaskForceMovement(ctx, st, taskForce, playerSubzone, dt);
            updateStrategicStealthOperations(ctx, st, taskForce, playerSubzone);
            updateStrategicTaskForceEncounter(ctx, st, taskForce, playerSubzone);
        }
    }

    private static StrategicRoleProfile friendlyStrategicRoleProfile(GameContext ctx, CampaignState st) {
        StrategicRoleProfile profile = new StrategicRoleProfile();
        if (ctx != null && ctx.player != null && ctx.player.role != null && ctx.player.alive && !ctx.player.dying && ctx.player.hp > 0) {
            accumulateRole(profile, ctx.player.role);
        }
        if (st == null) return profile;
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed || entry.role == null) continue;
            accumulateRole(profile, entry.role);
        }
        return profile;
    }

    private static StrategicRoleProfile friendlyStrategicRoleProfileInSubzone(GameContext ctx, CampaignState st, int subzone) {
        StrategicRoleProfile profile = new StrategicRoleProfile();
        if (subzone < 0) return profile;
        if (ctx != null && ctx.player != null && ctx.player.role != null && ctx.player.alive && !ctx.player.dying && ctx.player.hp > 0) {
            int playerCurrentSubzone = ensureShipMissionSubzone(ctx, ctx.player);
            if (playerCurrentSubzone == subzone) {
                accumulateRole(profile, ctx.player.role);
            }
        }
        if (st == null) return profile;
        if (!st.strategicDivisions.isEmpty()) {
            for (PersistentFleetEntry entry : st.persistentBlueFleet) {
                if (entry == null || entry.destroyed || entry.role == null) continue;
                int groupId = Math.max(CAMPAIGN_FLAGSHIP_COMMAND_GROUP, entry.commandGroupId);
                StrategicDivisionState division = st.strategicDivisions.get(groupId);
                if (division == null || division.currentSubzone != subzone) continue;
                accumulateRole(profile, entry.role);
            }
            return profile;
        }
        for (Ship ship : liveFriendlyShipsInSubzone(ctx, subzone)) {
            if (ship != null && ship.role != null) {
                accumulateRole(profile, ship.role);
            }
        }
        return profile;
    }

    private static void accumulateRole(StrategicRoleProfile profile, ShipRole role) {
        if (profile == null || role == null) return;
        if (role == ShipRole.STEALTH_SHIP || role == ShipRole.COMMAND_INTEL_TITAN || role == ShipRole.FLEET_TELEPORTER_TITAN) {
            profile.stealthHullCount++;
        }
        if (role.isCarrierHull() || role == ShipRole.CARRIER_SUPPORT_TITAN) {
            profile.carrierHullCount++;
        }
        if (role == ShipRole.BATTLESHIP || role == ShipRole.BATTLECRUISER || role == ShipRole.DREADNOUGHT
                || role == ShipRole.SUPERSHIP || role == ShipRole.BULWARK_TITAN
                || role == ShipRole.MOBILE_STATION_TITAN || role == ShipRole.VANGUARD_TITAN
                || role == ShipRole.INTERDICTION_TITAN || role == ShipRole.SHIELD_BASTION_TITAN
                || role == ShipRole.ELITE_SUPERSHIP_COMMAND_TITAN || role == ShipRole.ELITE_REINFORCEMENTS_TITAN
                || role == ShipRole.HYPERWEAPON_TITAN || role == ShipRole.MOTHERSHIP) {
            profile.heavyHullCount++;
        }
        if (role == ShipRole.ARTILLERY_SHIP || role == ShipRole.LIGHT_CRUISER || role == ShipRole.CRUISER
                || role == ShipRole.MEDIUM_CRUISER || role == ShipRole.BATTLECRUISER || role == ShipRole.MISSILE_BOAT
                || role == ShipRole.ARTILLERY_TITAN || role == ShipRole.HYPERWEAPON_TITAN
                || role == ShipRole.INTERDICTION_TITAN || role == ShipRole.VANGUARD_TITAN
                || role == ShipRole.ELITE_REINFORCEMENTS_TITAN) {
            profile.strikeHullCount++;
        }
        if (role == ShipRole.HAULER || role == ShipRole.TRANSPORT || role == ShipRole.MINER
                || role == ShipRole.TRANSPORT_TITAN || role == ShipRole.BOARDING_RECOVERY_TITAN
                || role == ShipRole.MOBILE_STATION_TITAN || role == ShipRole.MOTHERSHIP) {
            profile.logisticsHullCount++;
        }
        if (role == ShipRole.PICKET || role == ShipRole.PATROL || role == ShipRole.CIWS_CORVETTE
                || role == ShipRole.FRIGATE || role == ShipRole.PD_CRAFT || role == ShipRole.SHIELD_BASTION_TITAN
                || role == ShipRole.COMMAND_INTEL_TITAN) {
            profile.screenHullCount++;
        }
    }

    private static double strategicRoleOperationalMultiplier(StrategicRoleProfile profile) {
        if (profile == null) return 1.0;
        double operationalBonus = 1.0
                + profile.carrierProjection() * 0.05
                + profile.stealthCoverage() * 0.04
                + profile.screenCoverage() * 0.03;
        double logisticsPenalty = Math.max(0.82, 1.0 - Math.max(0.0, profile.heavyPresence() - profile.logisticsSupport()) * 0.12);
        return profile.roleCoverageBonus() * operationalBonus * logisticsPenalty;
    }

    private static double rawHeavyCommandWeight(CampaignState st) {
        if (st == null) return 0.0;
        StrategicRoleProfile profile = new StrategicRoleProfile();
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed || entry.role == null) continue;
            accumulateRole(profile, entry.role);
        }
        return MathUtil.clamp(
                profile.heavyPresence() * 0.75
                        + profile.strikeReach() * 0.40
                        - profile.logisticsSupport() * 0.18,
                0.0,
                1.0);
    }

    private static void updateStrategicTaskForceMovement(GameContext ctx, CampaignState st,
                                                         StrategicTaskForce taskForce,
                                                         int playerSubzone,
                                                         double dt) {
        if (ctx == null || st == null || taskForce == null) return;
        if (taskForce.encounterSpawned && !taskForce.encounterResolved) return;
        taskForce.disruptionRemainingSec = Math.max(0.0, taskForce.disruptionRemainingSec - dt);
        taskForce.breakoffRemainingSec = Math.max(0.0, taskForce.breakoffRemainingSec - dt);
        StrategicRoleProfile roleProfile = friendlyStrategicRoleProfile(ctx, st);
        if (taskForce.disruptionRemainingSec > 1e-6) {
            taskForce.dwellRemainingSec = Math.max(taskForce.dwellRemainingSec, 4.0);
            return;
        }
        if (taskForce.transitRemainingSec > 0.0) {
            taskForce.transitRemainingSec = Math.max(0.0, taskForce.transitRemainingSec - dt);
            if (taskForce.transitRemainingSec <= 1e-6) {
                taskForce.currentSubzone = taskForce.targetSubzone;
                taskForce.dwellRemainingSec = 6.0 + ctx.rng.nextDouble() * 8.0;
            }
            return;
        }
        taskForce.dwellRemainingSec = Math.max(0.0, taskForce.dwellRemainingSec - dt);
        if (taskForce.dwellRemainingSec > 1e-6) return;

        List<Integer> neighbors = strategicNeighborSubzones(taskForce.currentSubzone);
        if (neighbors.isEmpty()) return;
        int next = chooseStrategicNextSubzone(ctx, st, taskForce, neighbors, playerSubzone, roleProfile);
        if (next < 0 || next == taskForce.currentSubzone) {
            taskForce.dwellRemainingSec = 5.0 + ctx.rng.nextDouble() * 6.0;
            return;
        }
        taskForce.targetSubzone = next;
        taskForce.transitRemainingSec = strategicTransitSeconds(taskForce, taskForce.currentSubzone, next, roleProfile);
    }

    private static void updateStrategicTaskForceEncounter(GameContext ctx, CampaignState st,
                                                          StrategicTaskForce taskForce,
                                                          int playerSubzone) {
        if (ctx == null || st == null || taskForce == null || !taskForce.hostile || !taskForce.spawnsEncounter) return;
        if (st.manualEncounterCommitInProgress) return;
        int contactSubzone = friendlyStrategicContactSubzone(ctx, st, taskForce, playerSubzone);
        if (contactSubzone < 0) return;
        StrategicRoleProfile roleProfile = friendlyStrategicRoleProfileInSubzone(ctx, st, contactSubzone);
        if (taskForce.kind == StrategicTaskForceKind.STEALTH) {
            double enemyStrength = strategicTaskForceThreat(taskForce, st.sector);
            double friendlyStrength = strategicFriendlyStrength(ctx, st, contactSubzone);
            if (taskForce.breakoffRemainingSec > 0.0
                    || friendlyStrength > enemyStrength * (1.35 + roleProfile.screenCoverage() * 0.35)
                    || enemyStrength < 28.0
                    || roleProfile.stealthCoverage() >= 0.24) {
                taskForce.breakoffRemainingSec = Math.max(taskForce.breakoffRemainingSec, 22.0);
                taskForce.dwellRemainingSec = 0.0;
                EventSystem.showBanner(ctx, "RAIDER CELL CLOAKS AND BREAKS CONTACT", 1.3);
                return;
            }
        }
        if (taskForce.kind == StrategicTaskForceKind.STRIKE && roleProfile.heavyPresence() >= 0.45) {
            taskForce.currentStrength = Math.max(0.0, taskForce.currentStrength - taskForce.maxStrength * 0.04);
            taskForce.disruptionRemainingSec = Math.max(taskForce.disruptionRemainingSec, 8.0);
        }
        if (!taskForce.encounterSpawned) {
            if (!hasPendingStrategicEncounterChoice(ctx)
                    || ctx.ui.strategicEncounterPrompt.taskForceId != taskForce.id) {
                beginStrategicEncounterChoice(ctx, st, taskForce, contactSubzone);
            }
            taskForce.transitRemainingSec = 0.0;
            taskForce.dwellRemainingSec = 999.0;
            return;
        }
        pruneStrategicTaskForceShips(ctx, taskForce);
        if (taskForce.spawnedShipIds.isEmpty()) {
            taskForce.encounterResolved = true;
            EventSystem.showBanner(ctx, "CONTACT CLEARED: " + taskForce.label.toUpperCase(Locale.US), 1.4);
        }
    }

    private static int friendlyStrategicContactSubzone(GameContext ctx,
                                                       CampaignState st,
                                                       StrategicTaskForce taskForce,
                                                       int playerSubzone) {
        if (ctx == null || st == null || taskForce == null || taskForce.currentSubzone < 0) return -1;
        if (playerSubzone >= 0 && taskForce.currentSubzone == playerSubzone) return playerSubzone;
        for (StrategicDivisionState division : st.strategicDivisions.values()) {
            if (division == null || division.transitRemainingSec > 0.0) continue;
            if (division.currentSubzone == taskForce.currentSubzone
                    && strategicDivisionShipCount(st, division.groupId) > 0) {
                return division.currentSubzone;
            }
        }
        return -1;
    }

    private static void pruneStrategicTaskForceShips(GameContext ctx, StrategicTaskForce taskForce) {
        if (ctx == null || taskForce == null || taskForce.spawnedShipIds.isEmpty()) return;
        taskForce.spawnedShipIds.removeIf(shipId -> {
            Ship ship = findShipById(ctx, shipId);
            return ship == null || !ship.alive || ship.dying || ship.hp <= 0;
        });
    }

    private static void updateStrategicStealthOperations(GameContext ctx, CampaignState st,
                                                         StrategicTaskForce taskForce,
                                                         int playerSubzone) {
        if (ctx == null || st == null || taskForce == null) return;
        if (taskForce.kind != StrategicTaskForceKind.STEALTH) return;
        if (taskForce.encounterResolved || taskForce.encounterSpawned) return;
        if (taskForce.currentSubzone < 0 || taskForce.currentSubzone == playerSubzone) return;
        if (taskForce.breakoffRemainingSec > 0.0) return;
        if (taskForce.dwellRemainingSec > 2.0 || taskForce.transitRemainingSec > 0.0) return;
        StrategicRoleProfile roleProfile = friendlyStrategicRoleProfile(ctx, st);
        if (roleProfile.stealthCoverage() >= 0.30 || roleProfile.screenCoverage() >= 0.28) {
            taskForce.breakoffRemainingSec = 18.0;
            taskForce.dwellRemainingSec = 0.0;
            return;
        }

        StrategicTaskForce victim = friendlyStrategicVictimInSubzone(st, taskForce.currentSubzone);
        if (victim != null) {
            double raidDamage = 0.55 - roleProfile.heavyPresence() * 0.08 - roleProfile.screenCoverage() * 0.12;
            victim.currentStrength = Math.max(0.0, victim.currentStrength - victim.maxStrength * Math.max(0.20, raidDamage));
            victim.disruptionRemainingSec = Math.max(victim.disruptionRemainingSec, 18.0);
            if (victim.currentStrength <= 1.0) {
                victim.encounterResolved = true;
                victim.encounterSpawned = false;
                victim.spawnedShipIds.clear();
            }
            taskForce.breakoffRemainingSec = 20.0;
            taskForce.dwellRemainingSec = 0.0;
            EventSystem.showBanner(ctx, "GHOST RAID: " + victim.label.toUpperCase(Locale.US) + " HIT", 1.4);
            return;
        }

        Ship asset = highValueShipInSubzone(ctx, st, taskForce.currentSubzone);
        if (asset != null) {
            int damage = Math.max(10, (int) Math.round(asset.hpMax * Math.max(0.08, 0.18 - roleProfile.screenCoverage() * 0.05 - roleProfile.heavyPresence() * 0.04)));
            asset.takeDamage(damage, asset.x, asset.y);
            taskForce.breakoffRemainingSec = 24.0;
            taskForce.dwellRemainingSec = 0.0;
            EventSystem.showBanner(ctx, "RAIDER STRIKE: " + displayShipName(asset, "ASSET").toUpperCase(Locale.US), 1.5);
            return;
        }

        RecoverableWreckSite wreck = recoverableWreckInSubzone(ctx, st, taskForce.currentSubzone);
        if (wreck != null) {
            wreck.claimed = true;
            taskForce.breakoffRemainingSec = 18.0;
            taskForce.dwellRemainingSec = 0.0;
            EventSystem.showBanner(ctx, "RAIDER CELL SCUTTLED A RECOVERY SITE", 1.4);
        }
    }

    private static void initializeStrategicDivisions(GameContext ctx, CampaignState st, int playerSubzone) {
        if (ctx == null || st == null) return;
        rebalancePersistentCommandGroups(st);
        StrategicDivisionState flagship = new StrategicDivisionState(
                CAMPAIGN_FLAGSHIP_COMMAND_GROUP,
                DivisionStance.RESERVE,
                playerSubzone);
        st.strategicDivisions.put(flagship.groupId, flagship);

        java.util.Set<Integer> seen = new java.util.LinkedHashSet<>();
        for (PersistentFleetEntry entry : st.persistentBlueFleet) {
            if (entry == null || entry.destroyed) continue;
            int groupId = Math.max(CAMPAIGN_FLAGSHIP_COMMAND_GROUP, entry.commandGroupId);
            if (!seen.add(groupId) || groupId == CAMPAIGN_FLAGSHIP_COMMAND_GROUP) continue;
            st.strategicDivisions.put(groupId, new StrategicDivisionState(groupId, defaultDivisionStance(entry), playerSubzone));
        }
        if (ctx.ui != null) {
            ctx.ui.selectedStrategicDivisionGroupId = CAMPAIGN_FLAGSHIP_COMMAND_GROUP;
        }
    }

    private static void updateStrategicDivisions(GameContext ctx, CampaignState st, int playerSubzone, double dt) {
        if (ctx == null || st == null || st.strategicDivisions.isEmpty()) return;
        for (StrategicDivisionState division : st.strategicDivisions.values()) {
            if (division == null) continue;
            if (division.groupId == CAMPAIGN_FLAGSHIP_COMMAND_GROUP) {
                division.currentSubzone = playerSubzone;
                division.targetSubzone = playerSubzone;
                division.transitRemainingSec = 0.0;
                continue;
            }
            if (division.transitRemainingSec > 0.0) {
                division.transitRemainingSec = Math.max(0.0, division.transitRemainingSec - Math.max(0.0, dt));
                if (division.transitRemainingSec <= 1e-6) {
                    division.currentSubzone = division.targetSubzone;
                }
            }
        }
    }

    private static void spawnStrategicTaskForceEncounter(GameContext ctx, CampaignState st, StrategicTaskForce taskForce) {
        if (ctx == null || st == null || taskForce == null) return;
        if (taskForce.currentStrength <= 1.0) {
            taskForce.encounterResolved = true;
            return;
        }
        double strengthFrac = (taskForce.maxStrength <= 1e-6)
                ? 1.0
                : MathUtil.clamp(taskForce.currentStrength / taskForce.maxStrength, 0.0, 1.0);
        double cx = missionSubzoneCenterX(ctx, st.sector, taskForce.currentSubzone);
        double cy = missionSubzoneCenterY(ctx, st.sector, taskForce.currentSubzone);
        switch (taskForce.kind) {
            case PATROL -> {
                if (strengthFrac > 0.34) {
                    strategicSpawn(ctx, taskForce, ShipRole.FRIGATE, taskForce.faction, cx + 100.0, cy - 70.0, taskForce.label + " Frigate");
                }
                if (strengthFrac > 0.18) {
                    strategicSpawn(ctx, taskForce, ShipRole.PICKET, taskForce.faction, cx - 120.0, cy + 80.0, "Patrol Screen");
                }
                if (st.sector >= 7 && strengthFrac > 0.76) {
                    strategicSpawn(ctx, taskForce, ShipRole.MISSILE_BOAT, taskForce.faction, cx + 160.0, cy + 110.0, "Patrol Missile Boat");
                }
            }
            case STRIKE -> {
                ShipRole spearhead = (st.sector >= 10) ? ShipRole.BATTLECRUISER : ShipRole.LIGHT_CRUISER;
                if (strengthFrac > 0.42) {
                    strategicSpawn(ctx, taskForce, spearhead, taskForce.faction, cx + 80.0, cy - 40.0, taskForce.label + " Spearhead");
                }
                if (strengthFrac > 0.20) {
                    strategicSpawn(ctx, taskForce, ShipRole.FRIGATE, taskForce.faction, cx - 150.0, cy + 90.0, "Strike Escort");
                }
                if (strengthFrac > 0.28) {
                    strategicSpawn(ctx, taskForce, ShipRole.CIWS_CORVETTE, taskForce.faction, cx + 170.0, cy + 120.0, "Strike Flak Screen");
                }
            }
            case STEALTH -> {
                if (strengthFrac > 0.24) {
                    strategicSpawn(ctx, taskForce, ShipRole.STEALTH_SHIP, taskForce.faction, cx + 60.0, cy - 30.0, taskForce.label);
                }
                if (strengthFrac > 0.16) {
                    strategicSpawn(ctx, taskForce, ShipRole.PICKET, taskForce.faction, cx - 140.0, cy + 90.0, "Raider Screen");
                }
            }
            case CONVOY -> {
                if (strengthFrac > 0.18) {
                    strategicSpawn(ctx, taskForce, ShipRole.TRANSPORT, taskForce.faction, cx, cy, taskForce.label);
                }
                if (strengthFrac > 0.12) {
                    strategicSpawn(ctx, taskForce, ShipRole.PATROL, taskForce.faction, cx + 110.0, cy - 70.0, "Convoy Escort");
                }
            }
            case SALVAGE -> {
                if (strengthFrac > 0.18) {
                    strategicSpawn(ctx, taskForce, ShipRole.HAULER, taskForce.faction, cx, cy, taskForce.label);
                }
                if (strengthFrac > 0.12) {
                    strategicSpawn(ctx, taskForce, ShipRole.PICKET, taskForce.faction, cx - 90.0, cy + 60.0, "Recovery Escort");
                }
            }
        }
        snapshotHostiles(ctx, st.knownHostiles);
    }

    public static boolean takeCommandOfPendingStrategicEncounter(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !hasPendingStrategicEncounterChoice(ctx)) return false;
        if (clearStaleStrategicPromptDuringManualEncounter(ctx, st)) return true;
        st.manualEncounterCommitInProgress = true;
        if (ctx.ui.strategicEncounterPrompt.kind == UiState.StrategicEncounterPrompt.Kind.GALAXY_SEARCH_GROUP) {
            GalaxySearchGroup group = galaxySearchGroupById(st, ctx.ui.strategicEncounterPrompt.galaxySearchGroupId);
            if (group == null && ctx.ui != null) {
                group = nearestHostileGalaxySearchGroup(st, ctx.ui.selectedCampaignContactX, ctx.ui.selectedCampaignContactY, 520.0);
            }
            if (group == null) {
                st.manualEncounterCommitInProgress = false;
                ctx.ui.clearStrategicEncounterPrompt();
                ctx.state = GameState.RUNNING;
                return false;
            }
            return retainManualEncounterCommitOnSuccess(st, launchGalaxySearchGroupEncounter(ctx, st, group));
        }
        if (ctx.ui.strategicEncounterPrompt.kind == UiState.StrategicEncounterPrompt.Kind.INSTALLATION_THREAT) {
            CampaignInstallationThreatCase threat = installationThreatCaseById(st, ctx.ui.strategicEncounterPrompt.installationThreatId);
            CampaignLocation location = campaignLocationById(st, ctx.ui.strategicEncounterPrompt.campaignLocationId);
            if (threat == null || location == null || !threat.active) {
                st.manualEncounterCommitInProgress = false;
                ctx.ui.clearStrategicEncounterPrompt();
                ctx.state = GameState.RUNNING;
                return false;
            }
            return retainManualEncounterCommitOnSuccess(st, launchInstallationThreatEncounter(ctx, st, location, threat));
        }
        if (ctx.ui.strategicEncounterPrompt.kind == UiState.StrategicEncounterPrompt.Kind.CAMPAIGN_LOCATION) {
            CampaignLocation location = campaignLocationById(st, ctx.ui.strategicEncounterPrompt.campaignLocationId);
            if (location == null || location.completed) {
                st.manualEncounterCommitInProgress = false;
                ctx.ui.clearStrategicEncounterPrompt();
                ctx.state = GameState.RUNNING;
                return false;
            }
            return retainManualEncounterCommitOnSuccess(st, launchCampaignLocationEncounter(ctx, st, location));
        }
        if (ctx.ui.strategicEncounterPrompt.kind == UiState.StrategicEncounterPrompt.Kind.CAMPAIGN_FORCE) {
            CampaignForce force = campaignForceById(st, ctx.ui.strategicEncounterPrompt.campaignForceId);
            if (force == null || force.destroyed) {
                st.manualEncounterCommitInProgress = false;
                ctx.ui.clearStrategicEncounterPrompt();
                ctx.state = GameState.RUNNING;
                return false;
            }
            return retainManualEncounterCommitOnSuccess(st, launchCampaignForceEncounter(ctx, st, force));
        }
        if (ctx.ui.strategicEncounterPrompt.kind == UiState.StrategicEncounterPrompt.Kind.CAMPAIGN_BATTLE) {
            boolean resolved = resolvePendingCampaignBattleIntervention(ctx, "JOIN");
            st.manualEncounterCommitInProgress = false;
            return resolved;
        }
        StrategicTaskForce taskForce = strategicTaskForceById(st, ctx.ui.strategicEncounterPrompt.taskForceId);
        if (taskForce == null || taskForce.encounterResolved) {
            st.manualEncounterCommitInProgress = false;
            ctx.ui.clearStrategicEncounterPrompt();
            ctx.state = GameState.RUNNING;
            return false;
        }
        if (!taskForce.encounterSpawned) {
            spawnStrategicTaskForceEncounter(ctx, st, taskForce);
            taskForce.encounterSpawned = true;
            taskForce.transitRemainingSec = 0.0;
            taskForce.dwellRemainingSec = 999.0;
        }
        st.strategicOvermapMode = false;
        st.galaxyEncounterActive = true;
        st.galaxyAmbientEncounterActive = false;
        st.activeGalaxyEncounterLocationId = "";
        st.activeGalaxyEncounterSearchGroupId = 0;
        clearActiveGalaxyEncounterForceRefs(st);
        ctx.ui.clearStrategicEncounterPrompt();
        ctx.state = GameState.RUNNING;
        EventSystem.showBanner(ctx, "TAKE COMMAND: " + taskForce.label.toUpperCase(Locale.US), 1.5);
        return true;
    }

    private static boolean retainManualEncounterCommitOnSuccess(CampaignState st, boolean launched) {
        if (!launched && st != null) st.manualEncounterCommitInProgress = false;
        return launched;
    }

    public static boolean autoResolvePendingStrategicEncounter(GameContext ctx) {
        CampaignState st = state(ctx);
        if (ctx == null || st == null || !hasPendingStrategicEncounterChoice(ctx)) return false;
        if (clearStaleStrategicPromptDuringManualEncounter(ctx, st)) return true;
        if (ctx.ui.strategicEncounterPrompt.kind == UiState.StrategicEncounterPrompt.Kind.GALAXY_SEARCH_GROUP) {
            GalaxySearchGroup group = galaxySearchGroupById(st, ctx.ui.strategicEncounterPrompt.galaxySearchGroupId);
            if (group == null) {
                ctx.ui.clearStrategicEncounterPrompt();
                ctx.state = GameState.RUNNING;
                return false;
            }
            return autoResolveGalaxySearchGroupEncounter(ctx, st, group);
        }
        if (ctx.ui.strategicEncounterPrompt.kind == UiState.StrategicEncounterPrompt.Kind.INSTALLATION_THREAT) {
            CampaignInstallationThreatCase threat = installationThreatCaseById(st, ctx.ui.strategicEncounterPrompt.installationThreatId);
            CampaignLocation location = campaignLocationById(st, ctx.ui.strategicEncounterPrompt.campaignLocationId);
            if (threat == null || location == null || !threat.active) {
                ctx.ui.clearStrategicEncounterPrompt();
                ctx.state = GameState.RUNNING;
                return false;
            }
            return autoResolveInstallationThreatEncounter(ctx, st, location, threat);
        }
        if (ctx.ui.strategicEncounterPrompt.kind == UiState.StrategicEncounterPrompt.Kind.CAMPAIGN_LOCATION) {
            CampaignLocation location = campaignLocationById(st, ctx.ui.strategicEncounterPrompt.campaignLocationId);
            if (location == null || location.completed) {
                ctx.ui.clearStrategicEncounterPrompt();
                ctx.state = GameState.RUNNING;
                return false;
            }
            return autoResolveCampaignLocationEncounter(ctx, st, location);
        }
        if (ctx.ui.strategicEncounterPrompt.kind == UiState.StrategicEncounterPrompt.Kind.CAMPAIGN_FORCE) {
            CampaignForce force = campaignForceById(st, ctx.ui.strategicEncounterPrompt.campaignForceId);
            if (force == null || force.destroyed) {
                ctx.ui.clearStrategicEncounterPrompt();
                ctx.state = GameState.RUNNING;
                return false;
            }
            return autoResolveCampaignForceEncounter(ctx, st, force);
        }
        if (ctx.ui.strategicEncounterPrompt.kind == UiState.StrategicEncounterPrompt.Kind.CAMPAIGN_BATTLE) {
            return resolvePendingCampaignBattleIntervention(ctx, "SUPPORT");
        }
        StrategicTaskForce taskForce = strategicTaskForceById(st, ctx.ui.strategicEncounterPrompt.taskForceId);
        if (taskForce == null || taskForce.encounterResolved) {
            ctx.ui.clearStrategicEncounterPrompt();
            ctx.state = GameState.RUNNING;
            return false;
        }

        int contactSubzone = Math.max(0, taskForce.currentSubzone);
        List<Ship> friendlies = liveFriendlyShipsInSubzone(ctx, contactSubzone);
        double friendlyStrength = strategicFriendlyStrength(ctx, st, contactSubzone);
        double enemyStrength = strategicTaskForceThreat(taskForce, st.sector);
        double ratio = friendlyStrength / Math.max(30.0, enemyStrength);

        applyStrategicAutoResolveDamage(ctx, friendlies, ratio, enemyStrength);
        syncPersistentFleetCasualties(ctx, st);
        syncPersistentFleetEntrySnapshots(ctx, st);

        taskForce.encounterResolved = true;
        taskForce.encounterSpawned = false;
        taskForce.spawnedShipIds.clear();
        taskForce.transitRemainingSec = 0.0;
        taskForce.dwellRemainingSec = 999.0;

        ctx.ui.clearStrategicEncounterPrompt();
        ctx.state = GameState.RUNNING;
        if (ratio >= 1.25) {
            EventSystem.showBanner(ctx, "AUTO-RESOLVE: DECISIVE VICTORY", 1.6);
        } else if (ratio >= 0.9) {
            EventSystem.showBanner(ctx, "AUTO-RESOLVE: CONTACT CLEARED WITH DAMAGE", 1.7);
        } else {
            EventSystem.showBanner(ctx, "AUTO-RESOLVE: PYRRHIC VICTORY", 1.7);
        }
        return true;
    }

    private static boolean clearStaleStrategicPromptDuringManualEncounter(GameContext ctx, CampaignState st) {
        if (ctx == null || st == null || !st.manualEncounterCommitInProgress || ctx.ui == null
                || !ctx.ui.strategicEncounterPrompt.active) return false;
        ctx.ui.clearStrategicEncounterPrompt();
        ctx.state = GameState.RUNNING;
        EventSystem.showBanner(ctx, "TACTICAL ENGAGEMENT ALREADY ACTIVE", 1.2);
        return true;
    }

    private static void beginStrategicEncounterChoice(GameContext ctx, CampaignState st,
                                                      StrategicTaskForce taskForce, int playerSubzone) {
        if (ctx == null || st == null || taskForce == null || ctx.ui == null) return;
        int reinforcements = pullNearbyStrategicDivisionsToContact(st, taskForce.currentSubzone);
        List<Ship> friendlies = liveFriendlyShipsInSubzone(ctx, playerSubzone);
        double friendlyStrength = strategicFriendlyStrength(ctx, st, playerSubzone);
        double enemyStrength = strategicTaskForceThreat(taskForce, st.sector);
        boolean stealthReveal = taskForce.kind == StrategicTaskForceKind.STEALTH;
        String title = stealthReveal
                ? "STEALTH CONTACT REVEALED: " + taskForce.label.toUpperCase(Locale.US)
                : "CONTACT: " + taskForce.label.toUpperCase(Locale.US);
        String body = strategicEncounterBody(taskForce)
                + (reinforcements > 0 ? " Nearby allied divisions are reinforcing this contact." : "");
        if (stealthReveal) {
            body = "Ghost trace resolved into " + taskForce.label + ". " + body;
        }
        ctx.ui.showStrategicEncounterPrompt(
                taskForce.id,
                title,
                body,
                localRangeBearingReadout(ctx,
                        missionSubzoneCenterX(ctx, st.sector, Math.max(0, taskForce.currentSubzone)),
                        missionSubzoneCenterY(ctx, st.sector, Math.max(0, taskForce.currentSubzone))),
                "Fleet " + Math.round(friendlyStrength) + "  Enemy " + Math.round(enemyStrength));
        ctx.state = GameState.PAUSED;
        EventSystem.showBanner(ctx,
                (stealthReveal ? "STEALTH REVEAL: " : (reinforcements > 0 ? "REINFORCING CONTACT: " : "CONTACT REPORT: "))
                        + taskForce.label.toUpperCase(Locale.US),
                1.4);
    }

    private static int pullNearbyStrategicDivisionsToContact(CampaignState st, int contactSubzone) {
        if (st == null || st.strategicDivisions.isEmpty() || contactSubzone < 0) return 0;
        int moved = 0;
        for (StrategicDivisionState division : st.strategicDivisions.values()) {
            if (division == null || division.groupId == CAMPAIGN_FLAGSHIP_COMMAND_GROUP) continue;
            if (division.transitRemainingSec > 0.0) continue;
            if (division.currentSubzone == contactSubzone) continue;
            if (manhattanSubzoneDistance(division.currentSubzone, contactSubzone) > 1) continue;
            division.targetSubzone = contactSubzone;
            division.currentSubzone = contactSubzone;
            division.transitRemainingSec = 0.0;
            division.lastOrderX = Double.NaN;
            division.lastOrderY = Double.NaN;
            moved++;
        }
        return moved;
    }

    private static StrategicTaskForce strategicTaskForceById(CampaignState st, int taskForceId) {
        if (st == null || taskForceId <= 0) return null;
        for (StrategicTaskForce taskForce : st.strategicTaskForces) {
            if (taskForce != null && taskForce.id == taskForceId) return taskForce;
        }
        return null;
    }

    private static GalaxySearchGroup galaxySearchGroupById(CampaignState st, int groupId) {
        if (st == null || groupId <= 0) return null;
        for (GalaxySearchGroup group : st.galaxySearchGroups) {
            if (group != null && group.id == groupId) return group;
        }
        return null;
    }

    private static GalaxySearchGroup anchoredGalaxySearchGroup(CampaignState st, String anchorLocationId) {
        if (st == null || anchorLocationId == null || anchorLocationId.isBlank()) return null;
        for (GalaxySearchGroup group : st.galaxySearchGroups) {
            if (group != null && anchorLocationId.equals(group.anchorLocationId)) return group;
        }
        return null;
    }

    private static boolean isFriendlyInstallationLocation(CampaignLocation location) {
        return location != null
                && location.type != CampaignLocationType.ENEMY_ACTIVITY
                && (location.type == CampaignLocationType.REPAIR_SITE || !location.services.isEmpty())
                && locationDisplayMarkerFaction(location) != Faction.ENEMY;
    }

    private static GalaxySearchGroup trackedHostileThreatForInstallation(GameContext ctx, CampaignState st, CampaignLocation location) {
        if (st == null || location == null || !isFriendlyInstallationLocation(location)) return null;
        GalaxySearchGroup best = null;
        double bestDist = Double.POSITIVE_INFINITY;
        for (GalaxySearchGroup group : st.galaxySearchGroups) {
            if (group == null || !group.hostile || !isTrackableInstallationThreat(group, location)) continue;
            double dist = Math.hypot(group.x - location.x, group.y - location.y);
            double threatRadius = installationThreatRadius(group, location);
            if (dist > threatRadius) continue;
            if (best == null || dist < bestDist) {
                best = group;
                bestDist = dist;
            }
        }
        return best;
    }

    private static boolean isTrackableInstallationThreat(GalaxySearchGroup group, CampaignLocation location) {
        if (group == null || location == null) return false;
        if (location.id != null && location.id.equals(group.anchorLocationId)) return true;
        if (group.visible || group.contactFadeSec > 0.0) return true;
        return group.contactConfidence == GalaxyContactConfidence.POSSIBLE_PATROL
                || group.contactConfidence == GalaxyContactConfidence.CONFIRMED_HOSTILE
                || group.contactConfidence == GalaxyContactConfidence.IDENTIFIED_TASK_FORCE;
    }

    private static double installationThreatRadius(GalaxySearchGroup group, CampaignLocation location) {
        double base = Math.max(220.0, group == null ? 220.0 : group.interceptRange * 0.92);
        if (group != null && location != null && location.id != null && location.id.equals(group.anchorLocationId)) {
            return Math.max(base, 420.0);
        }
        return base;
    }

    private static String hostileThreatOriginLabel(CampaignState st, GalaxySearchGroup group) {
        if (group == null) return "unknown hostile approach";
        CampaignLocation anchor = campaignLocationById(st, group.anchorLocationId);
        if (anchor != null) return trimmedOrFallback(anchor.name, "hostile approach lane");
        double x = Double.isFinite(group.lastKnownX) ? group.lastKnownX : group.x;
        double y = Double.isFinite(group.lastKnownY) ? group.lastKnownY : group.y;
        return "last known hostile track at X " + (int) Math.round(x) + " Y " + (int) Math.round(y);
    }

    private static CampaignInstallationThreatCase installationThreatCaseById(CampaignState st, int threatId) {
        if (st == null || threatId <= 0) return null;
        for (CampaignInstallationThreatCase threat : st.installationThreatCases) {
            if (threat != null && threat.id == threatId) return threat;
        }
        return null;
    }

    private static CampaignInstallationThreatCase scriptedInstallationThreatForLocation(CampaignState st, CampaignLocation location) {
        if (st == null || location == null) return null;
        for (CampaignInstallationThreatCase threat : st.installationThreatCases) {
            if (threat == null || !threat.active) continue;
            if (location.id.equals(threat.locationId)) return threat;
        }
        return null;
    }

    private static CampaignInstallationThreatCase registerInstallationThreatCase(CampaignState st,
                                                                                 String locationId,
                                                                                 String forceName,
                                                                                 String origin,
                                                                                 String warning,
                                                                                 double threatLevel) {
        if (st == null || locationId == null || locationId.isBlank()) return null;
        CampaignInstallationThreatCase existing = null;
        for (CampaignInstallationThreatCase threat : st.installationThreatCases) {
            if (threat != null && locationId.equals(threat.locationId) && threat.active) {
                existing = threat;
                break;
            }
        }
        if (existing != null) return existing;
        CampaignInstallationThreatCase created = new CampaignInstallationThreatCase(
                st.nextInstallationThreatCaseId++, locationId, forceName, origin, warning, threatLevel);
        st.installationThreatCases.add(created);
        return created;
    }

    private static void resolveInstallationThreatCase(CampaignState st, CampaignInstallationThreatCase threat) {
        if (st == null || threat == null) return;
        threat.active = false;
        if (st.activeInstallationThreatCaseId == threat.id) {
            st.activeInstallationThreatCaseId = 0;
        }
    }

    private static String strategicEncounterBody(StrategicTaskForce taskForce) {
        if (taskForce == null) return "Unknown contact report.";
        return switch (taskForce.kind) {
            case PATROL -> "Enemy patrol pocket detected. Auto-resolve for speed, or take command to fight the intercept yourself.";
            case STRIKE -> "Heavy strike group moving in strength. Direct command gives your formation space to work with.";
            case STEALTH -> "Stealth raider contact. Manual command is safer if you want to protect key ships and screen the flank.";
            case CONVOY -> "Convoy contact detected.";
            case SALVAGE -> "Salvage detachment detected.";
        };
    }

    private static boolean launchCampaignLocationEncounter(GameContext ctx, CampaignState st, CampaignLocation location) {
        if (ctx == null || st == null || location == null) return false;
        st.activeGalaxyEncounterLocationId = location.id;
        st.activeGalaxyEncounterSearchGroupId = 0;
        st.galaxyEncounterActive = true;
        st.galaxyAmbientEncounterActive = false;
        clearActiveGalaxyEncounterForceRefs(st);
        st.strategicOvermapMode = false;
        st.sector = Math.max(1, location.missionIndex);
        if (ctx.ui != null) {
            ctx.ui.clearStrategicEncounterPrompt();
        }
        ctx.state = GameState.RUNNING;
        EventSystem.showBanner(ctx, "TAKE COMMAND: " + location.name.toUpperCase(Locale.US), 1.5);
        startSector(ctx, st.sector);
        applyPreEntryMissionBombardment(ctx, st, location);
        captureActiveGalaxyEncounterForceRefsFromLiveShips(ctx, st);
        recordStructuredCampaignEvent(ctx, st, "campaign.transition.encounter_launch",
                "location=" + safeTelemetryValue(location.id)
                        + " label=" + safeTelemetryValue(location.name)
                        + " ambient=false"
                        + " missionSector=" + st.sector);
        return true;
    }

